// Declare global Howl/Howler from the CDN script
declare var Howl: any;
declare var Howler: any;

class NativeAudioManager {
    private static instance: NativeAudioManager;
    private sounds: Map<SoundName, any> = new Map();
    private isInitialized = false;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;

    private constructor() {
        this.init();
    }

    public static getInstance(): NativeAudioManager {
        if (!NativeAudioManager.instance) {
            NativeAudioManager.instance = new NativeAudioManager();
        }
        return NativeAudioManager.instance;
    }

    private init() {
        if (this.isInitialized) return;
        this.isInitialized = true;

        // Ensure Howler exists (CDN Loaded)
        if (typeof Howler === 'undefined') {
            console.error("Howler.js not found!");
            return;
        }

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        soundFiles.forEach(name => {
            const sound = new Howl({
                src: [`./sounds/${name}.mp3`],
                preload: true,
                volume: this.sfxVolume,
                // Default to Web Audio, but Howler handles fallbacks and decoding robustness better than raw API
                onloaderror: (id: any, err: any) => {
                    console.warn(`Howl failed to load ${name}:`, err);
                }
            });
            this.sounds.set(name, sound);
        });
    }

    public prime() {
        // Howler handles auto-unlocking on first interaction.
        // We can explicitly resume context just in case.
        if (typeof Howler !== 'undefined' && Howler.ctx && Howler.ctx.state === 'suspended') {
            Howler.ctx.resume();
        }
    }

    public play(name: SoundName) {
        const sound = this.sounds.get(name);
        if (sound) {
            sound.volume(this.sfxVolume); // Update volume in case it changed
            sound.play();
        }
    }

    public setSfxVolume(v: number) {
        this.sfxVolume = Math.max(0, Math.min(1, v));
        // Update all existing sounds
        this.sounds.forEach(sound => sound.volume(this.sfxVolume));
    }

    public setMusicVolume(v: number) {
        this.musicVolume = Math.max(0, Math.min(1, v));
        // Placeholder for music
    }
}

