class NativeAudioManager {
    private static instance: NativeAudioManager;
    // Store the preloaded audio elements template
    private soundTemplates: Map<SoundName, HTMLAudioElement> = new Map();
    private isInitialized = false;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;

    private constructor() {
        this.init();
    }

    public static getInstance(): NativeAudioManager {
        if (!NativeAudioManager.instance) {
            NativeAudioManager.instance = new NativeAudioManager();
        }
        return NativeAudioManager.instance;
    }

    private getSoundUrl(name: string): string {
        try {
            // Robust absolute URL construction
            return new URL(`sounds/${name}.mp3`, document.baseURI || window.location.href).href;
        } catch (e) {
            return `./sounds/${name}.mp3`;
        }
    }

    private init() {
        if (this.isInitialized) return;
        this.isInitialized = true;

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        soundFiles.forEach((name) => {
            const url = this.getSoundUrl(name);
            const audio = new Audio();
            audio.src = url;
            audio.preload = 'auto'; // Force browser to buffer
            audio.volume = this.sfxVolume;

            // Optional: Log errors if the HTML5 audio fails too, but usually it's silent or works
            audio.onerror = (e) => {
                console.warn(`Audio load failed for ${name} at ${url}`, e);
            };

            this.soundTemplates.set(name, audio);
        });
    }

    public prime() {
        // HTML5 Audio doesn't strictly need "priming" in the same way context does,
        // but playing a silent sound or resuming context helps in some browsers.
        // For HTML5 Audio, user interaction usually just unlocks the ability to .play()
        // We can try to load() everything again.
        this.soundTemplates.forEach(audio => {
            if (audio.readyState === 0) audio.load();
        });
    }

    public play(name: SoundName) {
        const template = this.soundTemplates.get(name);
        if (template) {
            // Clone the node to allow overlapping sounds (polyphony)
            // This is much more efficient than new Audio(url) every time
            const sound = template.cloneNode() as HTMLAudioElement;
            sound.volume = this.sfxVolume;

            // Play and catch autoplay errors
            const playPromise = sound.play();
            if (playPromise !== undefined) {
                playPromise.catch(error => {
                    // Auto-play was prevented or file not loaded yet
                    // console.warn(`Playback prevented for ${name}:`, error);
                });
            }
        }
    }

    public setSfxVolume(v: number) {
        this.sfxVolume = Math.max(0, Math.min(1, v));
        // We don't update playing sounds, but new clones will use this volume
    }

    public setMusicVolume(v: number) {
        this.musicVolume = Math.max(0, Math.min(1, v));
    }
}

