    private sfxGainNode: GainNode | null = null;
    private buffers: Map<SoundName, AudioBuffer> = new Map();
    private isInitialized = false;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;

    private constructor() {
        // Lazy init in prime() or first play to avoid autoplay policy issues immediately
    }

    public static getInstance(): NativeAudioManager {
        if (!NativeAudioManager.instance) {
            NativeAudioManager.instance = new NativeAudioManager();
        }
        return NativeAudioManager.instance;
    }

    private getContext(): AudioContext {
        if (!this.audioContext) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            this.audioContext = new AudioContextClass();
            this.sfxGainNode = this.audioContext.createGain();
            this.sfxGainNode.gain.value = this.sfxVolume;
            this.sfxGainNode.connect(this.audioContext.destination);
        }
        return this.audioContext;
    }

    /**
     * Constructs a robust absolute URL for the sound file.
     * Uses document.baseURI to handle subfolders (Itch.io) and local preview correctly.
     */
    private getSoundUrl(name: string): string {
        // We use the baseURI (location of index.html) to resolve the sounds folder.
        // new URL('sounds/foo.mp3', 'http://site.com/game/index.html') -> 'http://site.com/game/sounds/foo.mp3'
        // This automatically handles stripping 'index.html' or handling trailing slashes.
        try {
            const baseUrl = document.baseURI || window.location.href;
            const url = new URL(`sounds/${name}.mp3`, baseUrl);
            return url.href;
        } catch (e) {
            console.error("URL construction failed, falling back to relative", e);
            return `sounds/${name}.mp3`;
        }
    }

    public async init() {
        if (this.isInitialized) return;
        this.isInitialized = true;

        const ctx = this.getContext();

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        // Load all sounds
        await Promise.all(soundFiles.map(name => this.loadSound(name, ctx)));
    }

    private async loadSound(name: SoundName, ctx: AudioContext) {
        // Cache Busting: Force the browser to fetch a fresh copy.
        // This fixes issues where the browser cached a 404 HTML page as the "MP3".
        const url = this.getSoundUrl(name) + `?v=${Date.now()}`;

        try {
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
            }

            // SAFETY CHECK: Verify we didn't get an HTML 404 page (Soft 404)
            const contentType = response.headers.get('content-type');
            if (contentType && contentType.includes('text/html')) {
                throw new Error(`Server returned HTML (Soft 404) instead of Audio.`);
            }

            const arrayBuffer = await response.arrayBuffer();

            // Decode the audio
            // If this fails, it's a true corruption issue, but the checks above usually prevent
            // the "EncodingError" caused by parsing HTML as Audio.
            const audioBuffer = await ctx.decodeAudioData(arrayBuffer);
            this.buffers.set(name, audioBuffer);
            // console.log(`[Audio] Loaded ${name}`);

