/**
 * A lightweight procedural sound synthesizer using WebAudio API.
 * Acts as a fallback when audio files fail to load or play.
 */
class SynthFallback {
    private ctx: AudioContext | null = null;
    private volume: number = 0.5;

    constructor() {
        try {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            if (AudioContextClass) {
                this.ctx = new AudioContextClass();
            }
        } catch (e) {
            console.error("WebAudio not supported", e);
        }
    }

    public setVolume(v: number) {
        this.volume = v;
    }

    public resume() {
        if (this.ctx?.state === 'suspended') {
            this.ctx.resume();
        }
    }

    private playTone(freq: number, type: OscillatorType, duration: number, volMultiplier: number = 1) {
        if (!this.ctx) return;

        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = type;
        osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

        gain.gain.setValueAtTime(this.volume * volMultiplier, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start();
        osc.stop(this.ctx.currentTime + duration);
    }

    private playNoise(duration: number, volMultiplier: number = 1) {
        if (!this.ctx) return;

        const bufferSize = this.ctx.sampleRate * duration;
        const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
        const data = buffer.getChannelData(0);

        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }

        const noise = this.ctx.createBufferSource();
        noise.buffer = buffer;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(this.volume * volMultiplier, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

        noise.connect(gain);
        gain.connect(this.ctx.destination);
        noise.start();
    }

    public play(name: SoundName) {
        this.resume();
        // Mappings for sound effects to synth parameters
        switch (name) {
            case 'menu_click':
                this.playTone(800, 'sine', 0.1, 0.5);
                break;
            case 'draw':
                this.playNoise(0.1, 0.3); // Paper-like noise
                break;
            case 'play_resource':
                this.playTone(400, 'triangle', 0.15);
                break;
            case 'conscript_phy':
                this.playTone(150, 'sawtooth', 0.2);
                break;
            case 'conscript_mag':
                this.playTone(600, 'sine', 0.3, 0.5);
                break;
            case 'attack_phase':
                this.playTone(200, 'square', 0.3);
                break;
            case 'damage_sm':
                this.playNoise(0.2, 0.8);
                break;
            case 'damage_md':
                this.playNoise(0.3, 1.0);
                break;
            case 'damage_lg':
                this.playNoise(0.5, 1.2);
                break;
            case 'destroy':
                this.playNoise(0.4, 0.6);
                this.playTone(100, 'sawtooth', 0.4);
                break;
            case 'turn_start':
                this.playTone(440, 'sine', 0.5);
                break;
            case 'game_over':
                // Simple arpeggio
                if(this.ctx) {
                    const now = this.ctx.currentTime;
                    [300, 400, 500].forEach((f, i) => {
                         const osc = this.ctx!.createOscillator();
                         const g = this.ctx!.createGain();
                         osc.frequency.value = f;
                         g.gain.value = 0.2;
                         g.gain.linearRampToValueAtTime(0, now + 0.5 + i*0.2);
                         osc.connect(g); g.connect(this.ctx!.destination);
                         osc.start(now + i*0.1); osc.stop(now + 0.6 + i*0.1);
                    });
                }
                break;
            case 'tactic':
                this.playTone(880, 'sine', 0.3);
                break;
            default:
                this.playTone(300, 'sine', 0.1);
                break;
        }
    }
}

class NativeAudioManager {
    private static instance: NativeAudioManager;
    private sounds: Map<SoundName, HTMLAudioElement> = new Map();
    private synth: SynthFallback;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;
    private initialized = false;

    private constructor() {
        this.synth = new SynthFallback();
    }

    public static getInstance(): NativeAudioManager {
        if (!NativeAudioManager.instance) {
            NativeAudioManager.instance = new NativeAudioManager();
        }
        return NativeAudioManager.instance;
    }

    private getSoundUrl(name: string): string {
        // Standard relative path. Browsers handle this best.
        return `sounds/${name}.mp3`;
    }

    public init() {
        if (this.initialized) return;
        this.initialized = true;

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        soundFiles.forEach(name => {
            const audio = new Audio(this.getSoundUrl(name));
            audio.preload = 'auto';
            audio.volume = this.sfxVolume;

            // If the audio fails to load or play, we just won't rely on it
            // The play() method below has a fallback.
            audio.onerror = () => {
                console.warn(`[Audio] Error loading ${name}, will use synth fallback.`);
            };

            this.sounds.set(name, audio);
        });
    }

    public prime() {
        this.init();
        this.synth.resume();
    }

    public play(name: SoundName) {
        if (!this.initialized) this.init();

        const audio = this.sounds.get(name);

        // Strategy: Try to play the MP3. If it fails (promise rejects) or doesn't exist, use Synth.
        if (audio) {
            // Reset time to allow rapid replay
            audio.currentTime = 0;
            audio.volume = this.sfxVolume;

            const playPromise = audio.play();

            if (playPromise !== undefined) {
                playPromise.catch(error => {
                    // This catches:
                    // 1. "NotSupportedError" (File corrupted/bad mime)
                    // 2. "NotAllowedError" (No user interaction yet)
                    // 3. "AbortError"

                    // If it's interaction error, synth might also fail, but worth a try.
                    // If it's a file error, synth will save the day.

                    // Only log warnings for non-interaction errors to avoid console spam
                    if (error.name !== 'NotAllowedError') {
                        // console.warn(`[Audio] File playback failed for ${name}, using synth.`);
                    }

                    this.synth.play(name);
                });
            }
        } else {
            this.synth.play(name);
        }
    }

    public setSfxVolume(v: number) {
        this.sfxVolume = Math.max(0, Math.min(1, v));
        this.synth.setVolume(v);
        this.sounds.forEach(audio => {
            audio.volume = this.sfxVolume;
        });
    }

    public setMusicVolume(v: number) {
        this.musicVolume = Math.max(0, Math.min(1, v));
    }
}

