class WebAudioManager {
    private static instance: WebAudioManager;
    private ctx: AudioContext;
    private buffers: Map<SoundName, AudioBuffer> = new Map();
    private isInitialized = false;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;

    private constructor() {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        this.ctx = new AudioContextClass();
    }

    public static getInstance(): WebAudioManager {
        if (!WebAudioManager.instance) {
            WebAudioManager.instance = new WebAudioManager();
        }
        return WebAudioManager.instance;
    }

    private getSoundUrl(name: string): string {
        return `sounds/${name}.mp3`;
    }

    public async init() {
        if (this.isInitialized) return;
        this.isInitialized = true;

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        // Load all sounds in parallel
        await Promise.all(soundFiles.map(name => this.loadSound(name)));
        console.log(`[Audio] Loaded ${this.buffers.size} sounds into memory.`);
    }

    private async loadSound(name: SoundName) {
        const url = this.getSoundUrl(name);
        try {
            const response = await fetch(url);
            if (!response.ok) {
                console.warn(`[Audio] Failed to fetch ${name}: ${response.status}`);
                return;
            }
            const arrayBuffer = await response.arrayBuffer();
            // decodeAudioData requires a callback in older browsers but returns a promise in modern ones.
            // We'll stick to the promise API as we are in a modern React context.
            const audioBuffer = await this.ctx.decodeAudioData(arrayBuffer);
            this.buffers.set(name, audioBuffer);
        } catch (error) {
            console.error(`[Audio] Failed to decode ${name}:`, error);
        }
    }

    public prime() {
        // Resume AudioContext on user interaction to unlock audio
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(e => console.warn("[Audio] Resume failed", e));
        }
        this.init();
    }

    public play(name: SoundName) {
        const buffer = this.buffers.get(name);
        if (!buffer) return;

        // Ensure context is running
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }

        try {
            const source = this.ctx.createBufferSource();
            source.buffer = buffer;

            const gainNode = this.ctx.createGain();
            gainNode.gain.value = this.sfxVolume;

            source.connect(gainNode);
            gainNode.connect(this.ctx.destination);

            source.start(0);
        } catch (e) {
            console.warn(`[Audio] Error playing ${name}`, e);
        }
    }

    public setSfxVolume(v: number) {
        this.sfxVolume = Math.max(0, Math.min(1, v));
    }

    public setMusicVolume(v: number) {
        this.musicVolume = Math.max(0, Math.min(1, v));
    }
