class AudioManager {
    private static instance: AudioManager;
    private sounds: Map<SoundName, HTMLAudioElement> = new Map();
    private sfxVolume = 0.5;
    private musicVolume = 0.5;
    private initialized = false;

    private constructor() {}

    public static getInstance(): AudioManager {
        if (!AudioManager.instance) {
            AudioManager.instance = new AudioManager();
        }
        return AudioManager.instance;
    }

    private getSoundUrl(name: string): string {
        return `sounds/${name}.mp3`;
    }

    public init() {
        if (this.initialized) return;
        this.initialized = true;

        const soundFiles: SoundName[] = [
            'attack_phase', 'conscript_mag', 'conscript_phy', 'damage_sm',
            'damage_md', 'damage_lg', 'destroy', 'draw', 'game_over',
            'king', 'menu_click', 'play_resource', 'queen',
            'swap_resource', 'tactic', 'turn_start'
        ];

        console.log("[Audio] Initializing Audio Manager...");

        soundFiles.forEach(name => {
            this.loadSound(name);
        });
    }

    private loadSound(name: SoundName) {
        const url = this.getSoundUrl(name);
        const audio = new Audio();

        // 1. Set CORS before SRC. This is critical for Itch/CDN.
        audio.crossOrigin = "anonymous";
        audio.src = url;
        audio.preload = 'auto';

        // 2. Define a Retry Mechanism for Local/Preview environments
        const retryWithoutCORS = () => {
            // Unbind the error handler to avoid infinite loops if it still fails
            audio.onerror = null;

            console.warn(`[Audio] CORS load failed for ${name}. Retrying without CORS...`);

            // Clear the source and the crossOrigin attribute completely
            audio.removeAttribute('crossorigin');
            audio.crossOrigin = null;

            // Force a reload by resetting src
            audio.src = url;
            audio.load();
        };

        // 3. Attach robust error handler
        audio.onerror = (e) => {
            const err = audio.error;
            let errorMsg = "Unknown Error";
            if (err) {
                switch(err.code) {
                    case 1: errorMsg = "Aborted"; break;
                    case 2: errorMsg = "Network Error"; break;
                    case 3: errorMsg = "Decoding Error"; break;
                    case 4: errorMsg = "Source Not Supported (404 or CORS)"; break;
                }
            }

            // If we get a generic "Source Not Supported" (Code 4), it's often a CORS block 
            // on localhost, or a 404. We try the non-CORS fallback once.
            if (err && err.code === 4 && audio.crossOrigin === "anonymous") {
                retryWithoutCORS();
                return;
            }

            console.warn(`[Audio] Final Error loading ${name}: ${errorMsg}`, err);
        };

        // 4. Store it
        this.sounds.set(name, audio);
    }

    public prime() {
        this.init();
    }

    public play(name: SoundName) {
        if (!this.initialized) this.init();

        const original = this.sounds.get(name);
        if (original) {
            // Clone the node to allow polyphony (overlapping sounds)
