class SynthAudioManager {
    private static instance: SynthAudioManager;
    private ctx: AudioContext | null = null;
    private sfxVolume = 0.5;
    private musicVolume = 0.5;
    private initialized = false;

    private constructor() {}

    public static getInstance(): SynthAudioManager {
        if (!SynthAudioManager.instance) {
            SynthAudioManager.instance = new SynthAudioManager();
        }
        return SynthAudioManager.instance;
    }

    public init() {
        if (this.initialized) return;

        try {
            // @ts-ignore - Handle cross-browser AudioContext
            const AudioContextClass = window.AudioContext || window.webkitAudioContext;
            this.ctx = new AudioContextClass();
            this.initialized = true;
            console.log("[Audio] Synth System Initialized");
        } catch (e) {
            console.warn("[Audio] Web Audio API not supported", e);
        }
    }

    public prime() {
        this.init();
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume();
        }
    }

    // --- SYNTHESIZER FUNCTIONS ---

    private createOscillator(type: OscillatorType, freq: number, duration: number, startTime: number) {
        if (!this.ctx) return;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = type;
        osc.frequency.setValueAtTime(freq, startTime);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        // Envelope
        gain.gain.setValueAtTime(this.sfxVolume, startTime);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);

        osc.start(startTime);
        osc.stop(startTime + duration);
    }

    private createNoise(duration: number) {
        if (!this.ctx) return;
        const bufferSize = this.ctx.sampleRate * duration;
        const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
        const data = buffer.getChannelData(0);

        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }

        const noise = this.ctx.createBufferSource();
        noise.buffer = buffer;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(this.sfxVolume * 0.5, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

        noise.connect(gain);
        gain.connect(this.ctx.destination);
        noise.start();
    }

    // --- SOUND DEFINITIONS ---

    public play(name: SoundName) {
        if (!this.initialized) this.init();
        if (!this.ctx) return;

        // Ensure context is running (sometimes browsers suspend it)
        if (this.ctx.state === 'suspended') {
            this.ctx.resume();
        }

        const t = this.ctx.currentTime;

        try {
            switch (name) {
                case 'menu_click':
                    // Short high blip
                    this.createOscillator('sine', 800, 0.1, t);
                    break;

                case 'draw':
                    // Soft sliding noise
                    this.createNoise(0.15);
                    break;

                case 'play_resource':
                    // Low thud
                    this.createOscillator('triangle', 150, 0.15, t);
                    if(this.ctx) {
                        const osc = this.ctx.createOscillator();
                        const g = this.ctx.createGain();
                        osc.frequency.setValueAtTime(100, t);
                        osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.1);
                        g.gain.setValueAtTime(this.sfxVolume, t);
                        g.gain.linearRampToValueAtTime(0, t + 0.1);
                        osc.connect(g);
                        g.connect(this.ctx.destination);
                        osc.start(t);
                        osc.stop(t + 0.1);
                    }
                    break;

                case 'conscript_phy':
                    // Metallic clank (FM-ish square)
                    this.createOscillator('square', 220, 0.2, t);
                    this.createOscillator('sawtooth', 110, 0.2, t);
                    break;

                case 'conscript_mag':
                    // Magical sparkle (Sine arpeggio)
                    this.createOscillator('sine', 660, 0.3, t);
                    this.createOscillator('sine', 880, 0.3, t + 0.05);
                    this.createOscillator('sine', 1100, 0.3, t + 0.1);
                    break;

                case 'attack_phase':
                    // Alarm sound
                    this.createOscillator('sawtooth', 440, 0.1, t);
                    this.createOscillator('sawtooth', 440, 0.1, t + 0.15);
                    break;

                case 'damage_sm':
                    // Small hit
                    this.createNoise(0.1);
                    this.createOscillator('sawtooth', 100, 0.1, t);
                    break;

                case 'damage_md':
                    // Medium hit
                    this.createNoise(0.2);
                    this.createOscillator('sawtooth', 80, 0.2, t);
                    break;

                case 'damage_lg':
                    // Large hit
                    this.createNoise(0.4);
                    this.createOscillator('square', 60, 0.4, t);
                    break;

                case 'destroy':
                    // Crumble
                    this.createNoise(0.3);
                    this.createOscillator('sawtooth', 50, 0.3, t);
                    break;

                case 'tactic':
                case 'king':
                case 'queen':
                    // Special effect (Warp)
                    if (this.ctx) {
                        const osc = this.ctx.createOscillator();
                        const gain = this.ctx.createGain();
                        osc.frequency.setValueAtTime(200, t);
                        osc.frequency.linearRampToValueAtTime(800, t + 0.3); // Rise
                        gain.gain.setValueAtTime(this.sfxVolume, t);
                        gain.gain.linearRampToValueAtTime(0, t + 0.3);
                        osc.connect(gain);
                        gain.connect(this.ctx.destination);
                        osc.start(t);
                        osc.stop(t + 0.3);
                    }
                    break;

                case 'turn_start':
                    // Gentle bell
                    this.createOscillator('sine', 440, 0.5, t);
                    this.createOscillator('triangle', 880, 0.5, t);
                    break;

                case 'game_over':
                    // Sad descending tone
                    this.createOscillator('triangle', 300, 0.5, t);
                    this.createOscillator('triangle', 250, 0.5, t + 0.4);
                    this.createOscillator('triangle', 200, 1.0, t + 0.8);
                    break;

                default:
                    this.createOscillator('sine', 440, 0.1, t);
                    break;
            }
        } catch (e) {
            console.error("[Audio] Synth Error:", e);
        }
    }

    public setSfxVolume(v: number) {
        this.sfxVolume = Math.max(0, Math.min(1, v));
    }

    public setMusicVolume(v: number) {
        this.musicVolume = Math.max(0, Math.min(1, v));
    }
}

