                    if (error.name !== 'NotAllowedError' && error.name !== 'AbortError') {
                        console.warn(`[Audio] Playback error for ${name}:`, error);
                    }
                });
            }
        } else {
            console.warn(`[Audio] Sound not found in registry: ${name}`);
        }
    }

