                        </>
                    )}
                    {gameState.phase === Phase.ATTACK_DECLARE && isInteractive && (
                        <button id="btn-confirm-attackers" onClick={() => handlers.onPhaseAction('CONFIRM_ATTACK')} className="bg-rose-600 px-4 py-2 rounded-full text-white font-bold shadow-lg animate-pulse">
                            CONFIRM
                        </button>
                    )}
                    {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && isInteractive && (
                        <button id="btn-confirm-blocks" onClick={() => handlers.onPhaseAction('CONFIRM_BLOCK')} className="bg-blue-600 px-4 py-2 rounded-full text-white font-bold shadow-lg">
                            BLOCK
                        </button>
                    )}
                </div>
            </div>

            {/* Mobile Bottom Bar: Player Info & Hand */}
            <div className="bg-slate-900 border-t border-slate-800 shrink-0 z-30">
                {/* Info Strip */}
                <div className="h-10 flex items-center justify-between px-3 bg-slate-950 border-b border-slate-800">
                    <div className="flex items-center gap-3">
                        <span className="text-sm font-bold text-indigo-300">{bottomPlayer.name}</span>
                        <div id="bottom-life-total" className="flex items-center gap-1 text-red-500 font-black text-xl" ref={refs.bottomLifeRef}>
                            <Heart size={20} fill="currentColor" /> {bottomPlayer.life}
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <div className="text-xs text-slate-500" ref={refs.bottomDeckRef}>Deck: {gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</div>
                        <button 
                            ref={refs.bottomDiscardRef as React.RefObject<HTMLButtonElement>}
                            onClick={() => handlers.setViewingDiscard(gameState.mode === 'STREET' ? 'SHARED' : bottomPlayer.id)} 
                            className="text-slate-400 flex items-center gap-1 text-xs bg-slate-800 px-2 py-1 rounded"
                        >
                            <Trash2 size={14} /> {gameState.mode === 'STREET' ? gameState.players[0].discard.length + gameState.players[1].discard.length : bottomPlayer.discard.length}
                        </button>
                    </div>
                </div>

                {/* Hand Scroll */}
                <div 
                    className={`h-28 w-full flex items-center justify-center bg-slate-900/50 pb-2 overflow-hidden transition-all ${
                        bottomPlayer.hand.length > 8 ? '-space-x-[3.5rem]' : 
                        bottomPlayer.hand.length > 5 ? '-space-x-10' : 
                        bottomPlayer.hand.length > 3 ? '-space-x-6' : 
                        '-space-x-2'
                    }`} 
                    ref={refs.handRef}
                >
                    {bottomPlayer.hand.map((c, i) => {
                        const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);

                        let hasValidTarget = true;
                        if (c.rank === 'K') hasValidTarget = topPlayer.field.some(f => getEffectiveColor(f) === c.baseColor);
                        if (c.rank === 'Q') hasValidTarget = topPlayer.field.length > 0 || bottomPlayer.field.length > 0;

                        const isPlayable = isMainPhase && isInteractive && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost && hasValidTarget;

                        return (
                            <div 
                                key={c.id} 
                                id={c.id} 
                                style={{ zIndex: i }}
                                className={`
                                    shrink-0 scale-90 origin-bottom transition-all duration-300
                                    ${isSelected ? '-translate-y-8 z-30' : 'active:-translate-y-8 active:scale-100 active:z-40 hover:-translate-y-8 hover:scale-100 hover:z-40'}
                                    ${dragState?.cardId === c.id ? 'opacity-0' : ''}
                                `}
                            >
                                <CardDisplay 
                                    card={c} 
                                    onClick={() => handlers.onCardClick(c, 'HAND', bottomPlayer.id)}
                                    onMouseDown={(e) => handlers.onDragStart(e, c, 'HAND', bottomPlayer.id)}
                                    isPlayable={isPlayable}
                                    isSelected={isSelected}
                                    isDragging={dragState?.cardId === c.id}
                                    size="md"
                                />
                            </div>
                        );
                    })}
                </div>
            </div>

            {dragState && dragState.sourceType === 'HAND' && (
                <div 
                    className="fixed pointer-events-none z-[100]"
                    style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
                >
                    <CardDisplay card={dragState.cardObj!} size="md" isDragging />
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState, useRef } from 'react';
import { TutorialStep } from '../../types';
import { ArrowRight } from 'lucide-react';

interface TutorialOverlayProps {
    step: TutorialStep;
    onNext?: () => void;
}

export const TutorialOverlay: React.FC<TutorialOverlayProps> = ({ step, onNext }) => {
    const [highlightStyle, setHighlightStyle] = useState<React.CSSProperties | null>(null);
    const [textStyle, setTextStyle] = useState<React.CSSProperties>({
        right: '5%',
        top: '20%',
    });
    const rafRef = useRef<number>(0);

    const updateHighlight = () => {
        const mode = step.highlightMode || 'MASK';
        const isMobile = window.innerWidth < 768;

        // 1. Highlight Box Calculation
        if (step.highlightElementId && mode !== 'NONE') {
            const el = document.getElementById(step.highlightElementId);
            if (el) {
                const rect = el.getBoundingClientRect();

                if (mode === 'MASK') {
                    setHighlightStyle({
                        position: 'fixed',
                        top: rect.top - 4,
                        left: rect.left - 4,
                        width: rect.width + 8,
                        height: rect.height + 8,
                        borderRadius: '8px',
                        boxShadow: '0 0 0 9999px rgba(0, 0, 0, 0.7)', 
                        zIndex: 140,
                        pointerEvents: 'none',
                        transition: 'all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1)'
                    });
                } else if (mode === 'OUTLINE') {
                    setHighlightStyle({
                        position: 'fixed',
                        top: rect.top - 4,
                        left: rect.left - 4,
                        width: rect.width + 8,
                        height: rect.height + 8,
                        borderRadius: '8px',
                        border: '4px solid #f59e0b', // Amber-500
                        zIndex: 140,
                        pointerEvents: 'none',
                        animation: 'pulse-border 2s infinite',
                        transition: 'all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1)'
                    });
                }

                // 2. Text Positioning Logic
                const centerX = rect.left + rect.width / 2;
                const centerY = rect.top + rect.height / 2;
                const screenW = window.innerWidth;
                const screenH = window.innerHeight;

                const newTextStyle: React.CSSProperties = {
                    position: 'fixed',
                    zIndex: 150,
                    maxWidth: isMobile ? 'none' : '350px',
                    width: isMobile ? '90%' : '90%',
                    transition: 'all 0.5s ease-out',
                    maxHeight: '60vh',
                    overflowY: 'auto'
                };

                const isTargetLow = centerY > screenH * 0.6;

                if (isMobile) {
                    newTextStyle.left = '5%';
                    newTextStyle.right = 'auto';
                    // Mobile docking: If target is Low, dock Top. If target is High, dock Bottom.
                    if (isTargetLow) {
                        newTextStyle.top = '70px'; // Clear of header
                        newTextStyle.bottom = 'auto';
                    } else {
                        newTextStyle.bottom = '20px'; // Clear of bottom interactions
                        newTextStyle.top = 'auto';
                    }
                } else {
                    // Desktop Logic: Float near element
                    if (isTargetLow) {
                        newTextStyle.bottom = '5%';
                        newTextStyle.top = 'auto'; 
                    } else {
                        let topPos = Math.max(100, centerY - 100);
                        if (topPos > screenH - 300) topPos = screenH - 300;
                        newTextStyle.top = `${topPos}px`;
                        newTextStyle.bottom = 'auto';
                    }

                    if (centerX < screenW / 2) {
                        const idealLeft = rect.right + 20;
                        if (idealLeft + 350 < screenW) {
                             newTextStyle.left = `${idealLeft}px`;
                        } else {
                             newTextStyle.right = '5%';
                        }
                    } else {
                        const idealRight = screenW - rect.left + 20;
                        if (screenW - idealRight - 350 > 0) {
                             newTextStyle.right = `${idealRight}px`;
                        } else {
                             newTextStyle.left = '5%';
                        }
                    }
                }
                setTextStyle(newTextStyle);

            } else {
                // Element not found, fallback
                if (mode === 'MASK') {
                     setHighlightStyle({
                        position: 'fixed',
                        inset: 0,
                        backgroundColor: 'rgba(0,0,0,0.7)',
                        zIndex: 140,
                    });
                } else {
                    setHighlightStyle(null);
                }
                setTextStyle({ 
                    right: 'auto', left: '5%', top: '20%', bottom: 'auto',
                    position: 'fixed', zIndex: 150, width: '90%', maxWidth: isMobile ? 'none' : '350px' 
                });
            }
        } else {
            // No highlight (general phase)
            if (mode === 'MASK' && !step.highlightElementId) {
                setHighlightStyle({
                    position: 'fixed',
                    inset: 0,
                    backgroundColor: 'rgba(0,0,0,0.7)',
                    zIndex: 140,
                });
            } else {
                setHighlightStyle(null);
            }
            setTextStyle({ 
                right: 'auto', left: '5%', top: isMobile ? '70px' : '20%', bottom: 'auto',
                position: 'fixed', zIndex: 150, width: '90%', maxWidth: isMobile ? 'none' : '350px' 
            });
        }
        rafRef.current = requestAnimationFrame(updateHighlight);
    };

    useEffect(() => {
        updateHighlight();
        return () => cancelAnimationFrame(rafRef.current);
    }, [step.highlightElementId, step.highlightMode]);

    return (
        <>
            <style>{`
                @keyframes pulse-border {
                    0% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); border-color: rgba(245, 158, 11, 1); }
                    70% { box-shadow: 0 0 0 10px rgba(245, 158, 11, 0); border-color: rgba(245, 158, 11, 0.5); }
                    100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0); border-color: rgba(245, 158, 11, 1); }
                }
            `}</style>

            {/* The Highlight Element (Mask or Outline) */}
            {highlightStyle && <div style={highlightStyle} />}

            {/* Instruction Text */}
            <div style={textStyle} className="animate-in fade-in zoom-in duration-300 pointer-events-auto">
                <div className="bg-slate-900/95 backdrop-blur border-2 border-amber-500 rounded-xl p-3 md:p-6 shadow-[0_0_30px_rgba(245,158,11,0.3)] text-center relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-amber-500 to-transparent"></div>
                    <h3 className="text-amber-500 font-bold font-title uppercase tracking-widest text-[10px] md:text-sm mb-1 md:mb-2">Tutorial</h3>
                    <p className="text-white text-xs md:text-lg font-medium leading-relaxed">{step.instructionText}</p>

                    {step.requiredAction !== 'NONE' && step.targetId !== 'btn-tutorial-next' && (
                        <div className="mt-2 md:mt-4 text-[9px] md:text-xs text-slate-400 font-bold uppercase tracking-wider animate-pulse">
                            Action Required: {step.requiredAction.replace('CLICK_', 'Select ').replace('UI_BUTTON', 'Button')}
                        </div>
                    )}

                    {step.requiredAction === 'CLICK_UI_BUTTON' && step.targetId === 'btn-tutorial-next' && onNext && (
                         <div className="mt-2 md:mt-4 flex justify-center">
                            <button 
                                onClick={onNext}
                                className="bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 md:px-6 md:py-2 text-xs md:text-base rounded-lg font-bold shadow-lg flex items-center gap-2 transform transition-all active:scale-95 animate-pulse"
                            >
                                Continue <ArrowRight size={14} className="md:w-4 md:h-4" />
                            </button>
                         </div>
                    )}

                    {step.requiredAction === 'NONE' && (
                        <div className="mt-2 md:mt-4 text-[9px] md:text-xs text-slate-400 font-bold uppercase tracking-wider">
                            Watch closely...
                        </div>
                    )}

                    <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-amber-500 to-transparent"></div>
                </div>
            </div>
        </>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { GameMode, GameState, Card } from '../types';
import { sortHand } from '../utils/cards';
import { setGlobalSfxVolume, setGlobalMusicVolume } from '../utils/soundUtils';

export const useGameUI = () => {
    // Meta State
    const [menuStep, setMenuStep] = useState<'MODE' | 'PLAYERS' | 'TUTORIAL_MENU'>('MODE');
    const [selectedMode, setSelectedMode] = useState<GameMode | null>(null);
    const [isCoinFlipping, setIsCoinFlipping] = useState(false);
    const [isMobile, setIsMobile] = useState(false);
    const [showOptions, setShowOptions] = useState(false);

    // Persistent Settings
    const [autoSort, setAutoSort] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_autosort');
            return saved !== null ? JSON.parse(saved) : true;
        } catch { return true; }
    });
    const [sfxVolume, setSfxVolumeState] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_sfx_volume');
            return saved !== null ? parseFloat(saved) : 0.5;
        } catch { return 0.5; }
    });
    const [musicVolume, setMusicVolumeState] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_music_volume');
            return saved !== null ? parseFloat(saved) : 0.5;
        } catch { return 0.5; }
    });

    // Modal/Overlay State
    const [showEndTurnModal, setShowEndTurnModal] = useState(false);
    const [showResignModal, setShowResignModal] = useState(false);
    const [showQuitModal, setShowQuitModal] = useState(false);
    const [showMenu, setShowMenu] = useState(false);
    const [viewingDiscard, setViewingDiscard] = useState<'SHARED' | number | null>(null);
    const [showMobileLog, setShowMobileLog] = useState(false);

    // Sandbox State
    const [sandboxToolsOpen, setSandboxToolsOpen] = useState(false);
    const [sandboxSearchTerm, setSandboxSearchTerm] = useState("");
    const [sandboxTargetPlayer, setSandboxTargetPlayer] = useState<0 | 1>(0);
    const [selectedSandboxCard, setSelectedSandboxCard] = useState<Card | null>(null);
    const [cardActionTarget, setCardActionTarget] = useState<{card: Card, loc: string, ownerId: number, instanceId?: string} | null>(null);
    const [showPlaySetup, setShowPlaySetup] = useState(false);

    // Initialize Audio Engine with stored values on mount
    useEffect(() => {
        setGlobalSfxVolume(sfxVolume);
        setGlobalMusicVolume(musicVolume);
    }, []);

    useEffect(() => {
        const handleResize = () => {
            const isLandscape = window.matchMedia("(orientation: landscape)").matches;
            // If landscape, force desktop layout regardless of width (unless extremely small, but assuming phones > 500px width in landscape)
            if (isLandscape) {
                setIsMobile(false);
            } else {
                setIsMobile(window.innerWidth < 768);
            }
        };
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const toggleAutoSort = useCallback((setGameState: React.Dispatch<React.SetStateAction<GameState | null>>, getActiveDecisionPlayerId: (s: GameState) => number) => {
        setAutoSort(prev => {
            const next = !prev;
            localStorage.setItem('battle_autosort', JSON.stringify(next));
            if (!next) {
                 setGameState(prevGs => {
                    if(!prevGs) return null;
                    const activePid = getActiveDecisionPlayerId(prevGs);
                    const nextPlayers = [...prevGs.players];
                    nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
                    return { ...prevGs, players: nextPlayers };
                 });
            }
            return next;
        });
    }, []);

    const setSfxVolume = useCallback((v: number) => {
        setSfxVolumeState(v);
        setGlobalSfxVolume(v);
        localStorage.setItem('battle_sfx_volume', v.toString());
    }, []);

    const setMusicVolume = useCallback((v: number) => {
        setMusicVolumeState(v);
        setGlobalMusicVolume(v);
        localStorage.setItem('battle_music_volume', v.toString());
    }, []);

    const resetModals = useCallback(() => {
        setShowQuitModal(false);
        setShowResignModal(false);
        setShowMenu(false);
        setShowEndTurnModal(false);
        setViewingDiscard(null);
        setShowOptions(false);
    }, []);

    return {
        menuStep, setMenuStep,
        selectedMode, setSelectedMode,
        isCoinFlipping, setIsCoinFlipping,
        autoSort, toggleAutoSort, setAutoSort,
        isMobile,
        showOptions, setShowOptions,
        sfxVolume, setSfxVolume,
        musicVolume, setMusicVolume,
        showEndTurnModal, setShowEndTurnModal,
        showResignModal, setShowResignModal,
        showQuitModal, setShowQuitModal,
        showMenu, setShowMenu,
        viewingDiscard, setViewingDiscard,
        showMobileLog, setShowMobileLog,
        sandboxToolsOpen, setSandboxToolsOpen,
        sandboxSearchTerm, setSandboxSearchTerm,
        sandboxTargetPlayer, setSandboxTargetPlayer,
        selectedSandboxCard, setSelectedSandboxCard,
        cardActionTarget, setCardActionTarget,
        showPlaySetup, setShowPlaySetup,
        resetModals
    };
};

import React from 'react';
import { CardDisplay } from '../CardDisplay';
import { Color, Phase } from '../../types';
import { getEffectiveColor } from '../../utils/rules';
import { Menu, Heart, X, ArrowRight, ArrowUpCircle, RotateCcw, Sword, Trash2 } from 'lucide-react';
import { LogRenderer } from '../ui/LogRenderer';
import { LayoutProps } from './types';

export const MobileLayout: React.FC<LayoutProps> = ({
    gameState,
    topPlayer,
    bottomPlayer,
    activeDecisionPlayerId,
    isInteractive,
    dragState,
    handlers,
    refs,
    uiState
}) => {
    const getPhaseName = () => {
        switch(gameState?.phase) {
            case Phase.INIT_SELECT: return "Setup";
            case Phase.RESOURCE_START: return "Resource Step";
            case Phase.RESOURCE_ADD_SELECT: return "Select Card";
            case Phase.RESOURCE_SWAP_SELECT_HAND: return "Select to Swap";
            case Phase.RESOURCE_SWAP_SELECT_PILE: return "Select Pile";
            case Phase.MAIN: return "Main Phase";
            case Phase.ATTACK_DECLARE: return "Attack Declare";
            case Phase.BLOCK_DECLARE: return "Block Declare";
            case Phase.DAMAGE: return "Combat";
            case Phase.UPKEEP: return "Upkeep";
            case Phase.DRAW: return "Draw Step";
            case Phase.END: return "End Phase";
            case Phase.GAME_OVER: return "Game Over";
            default: return gameState?.phase || "";
        }
    };

    // Dynamic scale helper for crowded lanes
    // Default to larger size (scale-90) for visibility, shrink only when crowded
    const getLaneScaleClass = (count: number) => {
        return count > 6 ? 'scale-75 -m-4' : 'scale-90 -mx-1';
    };

    const isMainPhase = gameState.phase === Phase.MAIN;
    // Calculate pulse for end turn button
    const player = gameState.players[gameState.turnPlayer];
    const availableRes = player.resources.filter(r => !r.isTapped).length;
    const canPlayCard = player.hand.some(c => c.cost <= availableRes);
    const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);
    const canDoAnything = (canPlayCard || canAttack) && gameState.phase === Phase.MAIN;
    const isEndTurnPulse = canDoAnything && !gameState.isSandboxRun ? '' : 'ring-2 ring-indigo-400 animate-pulse';

    const topBlack = topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black);
    const topRed = topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red);
    const bottomBlack = bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black);
    const bottomRed = bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red);

    return (
        <div className="flex flex-col h-full bg-slate-950 select-none">
            {/* Mobile Top Bar: CPU Info */}
            <div className="h-14 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-3 shadow-md z-30 shrink-0">
