                            </button>
                        </>
                    )}
                    {(gameState.phase === Phase.RESOURCE_ADD_SELECT || gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND || gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE) && isInteractive && (
                        <button onClick={() => handlers.onPhaseAction('CANCEL_RESOURCE')} className="bg-slate-700 p-3 rounded-full text-white shadow-lg">
                            <X size={24} />
                        </button>
                    )}
                    {gameState.phase === Phase.MAIN && isInteractive && (
                        <>
                            {!bottomPlayer.hasAttackedThisTurn && (
                                <button id="btn-attack-phase" onClick={() => handlers.onPhaseAction('ATTACK_PHASE')} className="bg-rose-600 p-3 rounded-full text-white shadow-lg">
                                    <Sword size={24} />
                                </button>
                            )}
                            <button id="btn-end-turn" onClick={() => handlers.onPhaseAction('END_TURN')} className={`bg-slate-700 p-3 rounded-full text-white shadow-lg ${isEndTurnPulse}`}>
                                <ArrowRight size={24} />
                            </button>
                        </>
                    )}
                    {gameState.phase === Phase.ATTACK_DECLARE && isInteractive && (
                        <button id="btn-confirm-attackers" onClick={() => handlers.onPhaseAction('CONFIRM_ATTACK')} className="bg-rose-600 px-4 py-2 rounded-full text-white font-bold shadow-lg animate-pulse">
                            CONFIRM
                        </button>
                    )}
                    {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && isInteractive && (
                        <button id="btn-confirm-blocks" onClick={() => handlers.onPhaseAction('CONFIRM_BLOCK')} className="bg-blue-600 px-4 py-2 rounded-full text-white font-bold shadow-lg">
                            BLOCK
                        </button>
                    )}
                </div>
            </div>

            {/* Mobile Bottom Bar: Player Info & Hand */}
            <div className="bg-slate-900 border-t border-slate-800 shrink-0 z-30">
                {/* Info Strip */}
                <div className="h-10 flex items-center justify-between px-3 bg-slate-950 border-b border-slate-800">
                    <div className="flex items-center gap-3">
                        <span className="text-sm font-bold text-indigo-300">{bottomPlayer.name}</span>
                        <div id="bottom-life-total" className="flex items-center gap-1 text-red-500 font-black text-xl" ref={refs.bottomLifeRef}>
                            <Heart size={20} fill="currentColor" /> {bottomPlayer.life}
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <div className="text-xs text-slate-500" ref={refs.bottomDeckRef}>Deck: {gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</div>
                        <button 
                            ref={refs.bottomDiscardRef as React.RefObject<HTMLButtonElement>}
                            onClick={() => handlers.setViewingDiscard(gameState.mode === 'STREET' ? 'SHARED' : bottomPlayer.id)} 
                            className="text-slate-400 flex items-center gap-1 text-xs bg-slate-800 px-2 py-1 rounded"
                        >
                            <Trash2 size={14} /> {gameState.mode === 'STREET' ? gameState.players[0].discard.length + gameState.players[1].discard.length : bottomPlayer.discard.length}
                        </button>
                    </div>
                </div>

                {/* Hand Scroll */}
                <div 
                    className={`h-28 w-full flex items-center justify-center bg-slate-900/50 pb-2 overflow-hidden transition-all ${
                        bottomPlayer.hand.length > 8 ? '-space-x-[3.5rem]' : 
                        bottomPlayer.hand.length > 5 ? '-space-x-10' : 
                        bottomPlayer.hand.length > 3 ? '-space-x-6' : 
                        '-space-x-2'
                    }`} 
                    ref={refs.handRef}
                >
                    {bottomPlayer.hand.map((c, i) => {
                        const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);

                        let hasValidTarget = true;
                        if (c.rank === 'K') hasValidTarget = topPlayer.field.some(f => getEffectiveColor(f) === c.baseColor);
                        if (c.rank === 'Q') hasValidTarget = topPlayer.field.length > 0 || bottomPlayer.field.length > 0;

                        const isPlayable = isMainPhase && isInteractive && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost && hasValidTarget;

                        return (
                            <div 
                                key={c.id} 
                                id={c.id} 
                                style={{ zIndex: i }}
                                className={`
                                    shrink-0 scale-90 origin-bottom transition-all duration-300
                                    ${isSelected ? '-translate-y-8 z-30' : 'active:-translate-y-8 active:scale-100 active:z-40 hover:-translate-y-8 hover:scale-100 hover:z-40'}
                                    ${dragState?.cardId === c.id ? 'opacity-0' : ''}
                                `}
                            >
                                <CardDisplay 
                                    card={c} 
                                    onClick={() => handlers.onCardClick(c, 'HAND', bottomPlayer.id)}
                                    onMouseDown={(e) => handlers.onDragStart(e, c, 'HAND', bottomPlayer.id)}
                                    isPlayable={isPlayable}
                                    isSelected={isSelected}
                                    isDragging={dragState?.cardId === c.id}
                                    size="md"
                                />
                            </div>
                        );
                    })}
                </div>
            </div>

            {dragState && dragState.sourceType === 'HAND' && (
                <div 
                    className="fixed pointer-events-none z-[100]"
                    style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
                >
                    <CardDisplay card={dragState.cardObj!} size="md" isDragging />
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { GameMode, GameState, Card } from '../types';
import { sortHand } from '../utils/cards';
import { setGlobalSfxVolume, setGlobalMusicVolume } from '../utils/soundUtils';

export const useGameUI = () => {
    // Meta State
    const [menuStep, setMenuStep] = useState<'MODE' | 'PLAYERS' | 'TUTORIAL_MENU'>('MODE');
    const [selectedMode, setSelectedMode] = useState<GameMode | null>(null);
    const [isCoinFlipping, setIsCoinFlipping] = useState(false);
    const [isMobile, setIsMobile] = useState(false);
    const [showOptions, setShowOptions] = useState(false);

    // Persistent Settings
    const [autoSort, setAutoSort] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_autosort');
            return saved !== null ? JSON.parse(saved) : true;
        } catch { return true; }
    });
    const [sfxVolume, setSfxVolumeState] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_sfx_volume');
            return saved !== null ? parseFloat(saved) : 0.5;
        } catch { return 0.5; }
    });
    const [musicVolume, setMusicVolumeState] = useState(() => {
        try {
            const saved = localStorage.getItem('battle_music_volume');
            return saved !== null ? parseFloat(saved) : 0.5;
        } catch { return 0.5; }
    });

    // Modal/Overlay State
    const [showEndTurnModal, setShowEndTurnModal] = useState(false);
    const [showResignModal, setShowResignModal] = useState(false);
    const [showQuitModal, setShowQuitModal] = useState(false);
    const [showMenu, setShowMenu] = useState(false);
    const [viewingDiscard, setViewingDiscard] = useState<'SHARED' | number | null>(null);
    const [showMobileLog, setShowMobileLog] = useState(false);

    // Sandbox State
    const [sandboxToolsOpen, setSandboxToolsOpen] = useState(false);
    const [sandboxSearchTerm, setSandboxSearchTerm] = useState("");
    const [sandboxTargetPlayer, setSandboxTargetPlayer] = useState<0 | 1>(0);
    const [selectedSandboxCard, setSelectedSandboxCard] = useState<Card | null>(null);
    const [cardActionTarget, setCardActionTarget] = useState<{card: Card, loc: string, ownerId: number, instanceId?: string} | null>(null);
    const [showPlaySetup, setShowPlaySetup] = useState(false);

    // Initialize Audio Engine with stored values on mount
    useEffect(() => {
        setGlobalSfxVolume(sfxVolume);
        setGlobalMusicVolume(musicVolume);
    }, []);

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth < 768);
        };
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const toggleAutoSort = useCallback((setGameState: React.Dispatch<React.SetStateAction<GameState | null>>, getActiveDecisionPlayerId: (s: GameState) => number) => {
        setAutoSort(prev => {
            const next = !prev;
            localStorage.setItem('battle_autosort', JSON.stringify(next));
            if (!next) {
                 setGameState(prevGs => {
                    if(!prevGs) return null;
                    const activePid = getActiveDecisionPlayerId(prevGs);
                    const nextPlayers = [...prevGs.players];
                    nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
                    return { ...prevGs, players: nextPlayers };
                 });
            }
            return next;
        });
    }, []);

    const setSfxVolume = useCallback((v: number) => {
        setSfxVolumeState(v);
        setGlobalSfxVolume(v);
        localStorage.setItem('battle_sfx_volume', v.toString());
    }, []);

    const setMusicVolume = useCallback((v: number) => {
        setMusicVolumeState(v);
        setGlobalMusicVolume(v);
        localStorage.setItem('battle_music_volume', v.toString());
    }, []);

    const resetModals = useCallback(() => {
        setShowQuitModal(false);
        setShowResignModal(false);
        setShowMenu(false);
        setShowEndTurnModal(false);
        setViewingDiscard(null);
        setShowOptions(false);
    }, []);

    return {
        menuStep, setMenuStep,
        selectedMode, setSelectedMode,
        isCoinFlipping, setIsCoinFlipping,
        autoSort, toggleAutoSort, setAutoSort,
        isMobile,
        showOptions, setShowOptions,
        sfxVolume, setSfxVolume,
        musicVolume, setMusicVolume,
        showEndTurnModal, setShowEndTurnModal,
        showResignModal, setShowResignModal,
        showQuitModal, setShowQuitModal,
        showMenu, setShowMenu,
        viewingDiscard, setViewingDiscard,
        showMobileLog, setShowMobileLog,
        sandboxToolsOpen, setSandboxToolsOpen,
        sandboxSearchTerm, setSandboxSearchTerm,
        sandboxTargetPlayer, setSandboxTargetPlayer,
        selectedSandboxCard, setSelectedSandboxCard,
        cardActionTarget, setCardActionTarget,
        showPlaySetup, setShowPlaySetup,
        resetModals
    };
};

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth?: number;
}

export enum Phase {
  INIT_SELECT = 'INIT_SELECT', // Choosing initial resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START', // Decision: Play new or swap?
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  END = 'END',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  isCpu: boolean;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO' | 'SANDBOX' | 'TUTORIAL';

export interface LogEntry {
  id: string;
  text: string;
}

export interface TutorialState {
  active: boolean;
  lessonId?: string;
  currentStepIndex: number;
  steps: TutorialStep[];
  completed?: boolean;
}

export interface GameState {
  mode: GameMode;
  isSandboxRun?: boolean;
  isMultiBlockingEnabled?: boolean;
