import React, { useEffect, useState } from 'react';
import { Phase, GameMode } from './types';
import { addLog } from './utils/core';
import { createFieldCard } from './utils/rules';
import { RotateCcw, Play, Edit3, Trash2, GraduationCap, Volume2 } from 'lucide-react';
import { sortHand } from './utils/cards';
import { primeAudio, playSound } from './utils/soundUtils';

// Imported Components
import { CoinFlipOverlay } from './components/overlays/CoinFlipOverlay';
import { TurnChangeOverlay } from './components/overlays/TurnChangeOverlay';
import { TutorialOverlay } from './components/overlays/TutorialOverlay';
import { Confetti, Explosion, DamageOverlay } from './components/effects/VisualEffects';
import { Flyer, SpecialCardAnimation, SoulOrb } from './components/effects/GameAnimations';
import { MainMenu } from './components/screens/MainMenu';
import { MainMenuBackground } from './components/effects/MainMenuBackground';
import { SandboxTools } from './components/tools/SandboxTools';
import { EndTurnModal, ResignModal, QuitModal, PauseMenu } from './components/modals/GameModals';
import { OptionsMenu } from './components/modals/OptionsMenu';
import { DiscardModal } from './components/modals/DiscardModal';
import { MobileLayout } from './components/game/MobileLayout';
import { DesktopLayout } from './components/game/DesktopLayout';

// Hooks
import { useGameRefs } from './hooks/useGameRefs';
import { useGameEffects } from './hooks/useGameEffects';
import { useGameUI } from './hooks/useGameUI';
import { useGameState } from './hooks/useGameState';
import { useTutorial } from './hooks/useTutorial';
import { useGameAI } from './hooks/useGameAI';
import { useGameInteractions } from './hooks/useGameInteractions';

export const App: React.FC = () => {
  const refs = useGameRefs();
  const effects = useGameEffects();
  const ui = useGameUI();

  // Audio Priming State
  const [audioPrimed, setAudioPrimed] = useState(false);

  const { 
    gameState, setGameState, gameStateRef,
    startGame, drawCards, playCard, advancePhase, 
    performEndTurn, confirmAttack, confirmBlocks, 
    isDrawingInitialRef, getActiveDecisionPlayerId 
  } = useGameState({ effects, refs, autoSort: ui.autoSort });

  const { advanceTutorialStep, handleTutorialNext, isInteractionAllowed, handleGlobalClick } = useTutorial({
      gameState,
      setGameState,
      gameStateRef,
      performEndTurn,
      confirmBlocks,
      refs,
      effects
  });

  const interactions = useGameInteractions(gameState, {
      setGameState,
      gameStateRef,
      getActiveDecisionPlayerId,
      drawCards,
      playCard,
      advancePhase,
      confirmAttack,
      confirmBlocks
  }, effects, {
      isInteractionAllowed,
      advanceTutorialStep
  }, ui, refs);

  // Initialize AI Hook
  useGameAI({
      gameState,
      gameStateRef,
      actions: {
          setGameState,
          advancePhase,
          performEndTurn,
          playCard,
          confirmAttack,
          confirmBlocks,
          handleCardClick: interactions.handleCardClick,
          handleConfirmInitSelection: interactions.handleConfirmInitSelection,
          getActiveDecisionPlayerId
      },
      isCoinFlipping: ui.isCoinFlipping,
      showMenu: ui.showMenu,
      showTurnAnim: effects.showTurnAnim
  });

  const handleAppInteraction = () => {
      handleGlobalClick();
  };

  // --- Handlers wrapping UI logic ---
  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { ui.setMenuStep('TUTORIAL_MENU'); }
      else { ui.setSelectedMode(mode); ui.setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => { startGame('TUTORIAL', { p1: false, p2: true }, lessonId); };

  const handleStartGameClick = (isCpu: boolean) => { 
      if (ui.selectedMode) {
          startGame(ui.selectedMode, { p1: false, p2: isCpu }, undefined, ui.enableMultiBlocking);
          if (ui.selectedMode === 'STREET' || ui.selectedMode === 'PRO') {
              ui.setIsCoinFlipping(true);
          }
      }
  };

  const handleSpectateClick = () => { 
      if (ui.selectedMode) {
          startGame(ui.selectedMode, { p1: true, p2: true }, undefined, ui.enableMultiBlocking);
          if (ui.selectedMode === 'STREET' || ui.selectedMode === 'PRO') {
              ui.setIsCoinFlipping(true);
          }
      }
  };

  const handleQuitToTitle = () => {
      const isTutorial = gameState?.mode === 'TUTORIAL';
      setGameState(null);
      ui.resetModals();
      ui.setMenuStep(isTutorial ? 'TUTORIAL_MENU' : 'MODE');
  };

  const handleResign = () => {
      if (!gameState) return;
      playSound('game_over'); // Play sound on resign
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      ui.resetModals();
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!ui.cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const nextState = { ...prev, players: [...prev.players] };
          const p = nextState.players.find(pl => pl.id === ui.cardActionTarget!.ownerId)!;
          if (ui.cardActionTarget!.loc === 'HAND') {
              if (action === 'DELETE') { p.hand = p.hand.filter(c => c.id !== ui.cardActionTarget!.card.id); }
          } else if (ui.cardActionTarget!.loc === 'FIELD') {
              if (action === 'DELETE') { p.field = p.field.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
              else if (action === 'TAP') { const fc = p.field.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          } else if (ui.cardActionTarget!.loc === 'RESOURCE') {
               if (action === 'DELETE') { p.resources = p.resources.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
               else if (action === 'TAP') { const fc = p.resources.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          }
          return nextState;
      });
      ui.setCardActionTarget(null);
  };

  const startPlayFromHere = (isCpu: boolean) => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'STREET', phase: Phase.MAIN, isSandboxRun: true, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu } : p) };
      });
      ui.setShowPlaySetup(false); ui.setSandboxToolsOpen(false);
  };

  const returnToSandbox = () => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'SANDBOX', isSandboxRun: false, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu: false } : p) };
      });
      ui.setSandboxToolsOpen(true);
  };

  // Initial Draw Effect (Moved logic slightly to ensure it runs once)
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.mode !== 'TUTORIAL' && gameState.phase === Phase.INIT_SELECT && !ui.isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];
        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             // Add a small delay to ensure refs/layout are stable
             setTimeout(() => {
                 (async () => {
                     await drawCards(0, 8);
                     await drawCards(1, 8);
                     setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                     isDrawingInitialRef.current = false;
                 })();
             }, 200);
        }
      }
    }
  }, [gameState?.phase, ui.isCoinFlipping, gameState?.mode]);

  // --- AUDIO PRIMING OVERLAY (TITLE SCREEN) ---
  if (!audioPrimed) {
      return (
          <div 
              className="fixed inset-0 z-[9999] bg-slate-950 flex flex-col items-center justify-center cursor-pointer select-none"
              onClick={() => {
                  primeAudio();
                  setAudioPrimed(true);
              }}
          >
              <MainMenuBackground />

              <div className="relative z-10 flex flex-col items-center animate-in fade-in zoom-in duration-1000 space-y-12 p-4">

                  {/* Title Section */}
                  <div className="text-center space-y-6">
                      <div className="flex items-center justify-center gap-4 opacity-80">
                              <div className="h-px w-16 md:w-32 bg-gradient-to-r from-transparent via-indigo-500 to-transparent"></div>
                              <span className="text-indigo-400 text-xs md:text-sm font-bold tracking-[0.4em] uppercase font-title text-shadow-sm">Tactical Card Warfare</span>
                              <div className="h-px w-16 md:w-32 bg-gradient-to-r from-transparent via-indigo-500 to-transparent"></div>
                      </div>
                      <h1 className="text-7xl md:text-9xl font-black font-title tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-slate-100 via-slate-300 to-slate-500 drop-shadow-[0_4px_10px_rgba(0,0,0,0.5)]">
                          BATTLE
                      </h1>
                  </div>

                  {/* Start Prompt */}
                  <div className="animate-pulse mt-8">
                      <span className="text-white/80 font-bold tracking-[0.2em] text-lg md:text-xl border-b-2 border-transparent group-hover:border-indigo-500 transition-all">
                          CLICK TO START
                      </span>
                  </div>
              </div>
          </div>
      );
  }

  if (!gameState) {
      return (
        <div 
            className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30"
            onClick={handleAppInteraction}
        >
            <MainMenuBackground />
            <MainMenu 
                menuStep={ui.menuStep}
                setMenuStep={ui.setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
                onOpenOptions={() => ui.setShowOptions(true)}
                enableMultiBlocking={ui.enableMultiBlocking}
                setEnableMultiBlocking={ui.setEnableMultiBlocking}
            />
            {ui.showOptions && (
                <OptionsMenu 
                    onClose={() => ui.setShowOptions(false)}
                    autoSort={ui.autoSort}
                    toggleAutoSort={() => ui.toggleAutoSort(setGameState, getActiveDecisionPlayerId)}
                    sfxVolume={ui.sfxVolume}
                    setSfxVolume={ui.setSfxVolume}
                    musicVolume={ui.musicVolume}
                    setMusicVolume={ui.setMusicVolume}
                />
            )}
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? activeDecisionPlayerId : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;
  const tutorialComplete = gameState.tutorialState?.completed;

  const gameHandlers = {
      onCardClick: interactions.handleCardClick,
      onDragStart: interactions.handleDragStart,
      onPhaseAction: interactions.handlePhaseAction,
      setViewingDiscard: ui.setViewingDiscard,
      setShowMenu: ui.setShowMenu,
      toggleLog: () => ui.setShowMobileLog(!ui.showMobileLog)
  };

  return (
    <>
    <style>{`
        .lane-physical {
            background-image: repeating-linear-gradient(
                0deg,
                transparent,
                transparent 2px,
                rgba(0, 0, 0, 0.3) 2px,
                rgba(0, 0, 0, 0.3) 4px
            );
            background-size: 100% 4px;
        }

        .lane-magical {
            box-shadow: inset 0 0 20px rgba(220, 38, 38, 0.1);
            animation: pulse-magical 4s ease-in-out infinite;
        }

        @keyframes shake-1 { 0% { transform: translate(0, 0) } 25% { transform: translate(-2px, 2px) } 50% { transform: translate(2px, -2px) } 75% { transform: translate(-2px, -2px) } 100% { transform: translate(0, 0) } }
        @keyframes shake-2 { 0% { transform: translate(0, 0) } 25% { transform: translate(-4px, 4px) } 50% { transform: translate(4px, -4px) } 75% { transform: translate(-4px, -4px) } 100% { transform: translate(0, 0) } }
        @keyframes shake-3 { 0% { transform: translate(0, 0) } 25% { transform: translate(-6px, 6px) } 50% { transform: translate(6px, -6px) } 75% { transform: translate(-6px, -6px) } 100% { transform: translate(0, 0) } }
        @keyframes shake-4 { 0% { transform: translate(0, 0) } 25% { transform: translate(-8px, 8px) } 50% { transform: translate(8px, -8px) } 75% { transform: translate(-8px, -8px) } 100% { transform: translate(0, 0) } }
        .shake-1 { animation: shake-1 0.3s cubic-bezier(.36,.07,.19,.97) both; }
        .shake-2 { animation: shake-2 0.3s cubic-bezier(.36,.07,.19,.97) both; }
        .shake-3 { animation: shake-3 0.3s cubic-bezier(.36,.07,.19,.97) both; }
        .shake-4 { animation: shake-4 0.3s cubic-bezier(.36,.07,.19,.97) both; }
    `}</style>
    <div 
      className={`flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none ${effects.screenShake ? `shake-${effects.screenShake.intensity}` : ''}`} 
      ref={refs.containerRef}
      onMouseMove={(e) => {
          if (interactions.dragState) interactions.setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
      }}
      onMouseUp={(e) => interactions.handleDrop(e.nativeEvent)}
      onClick={handleAppInteraction}
    >
      {ui.isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    ui.setIsCoinFlipping(false);
                }} 
           />
      )}

      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} onNext={handleTutorialNext} />
      )}

      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <GraduationCap className="w-24 h-24 mx-auto text-emerald-500 animate-bounce" />
                  <h1 className="text-5xl md:text-7xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-500 drop-shadow-[0_0_25px_rgba(16,185,129,0.5)]">
                      TUTORIAL COMPLETE
                  </h1>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-bold text-xl shadow-lg shadow-emerald-500/30 transform transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                          <RotateCcw size={20} /> Return to Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.isSandboxRun && (
          <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top">
              <button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2">
                  <RotateCcw size={18}/> Return to Sandbox
              </button>
          </div>
      )}

      {ui.showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3">
                      <button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Vs CPU
                      </button>
                      <button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Hotseat
                      </button>
                  </div>
                  <button onClick={() => ui.setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}

      {ui.cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => ui.setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4">
                      <div className="w-32 h-44 bg-white rounded-md text-black flex items-center justify-center">
                          {ui.cardActionTarget.card.rank}{ui.cardActionTarget.card.suit}
                      </div>
                  </div>
                  <div className="flex gap-2 justify-center">
                      {ui.cardActionTarget.loc !== 'HAND' && (
                          <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                              <RotateCcw size={16}/> Tap/Untap
                          </button>
                      )}
                      <button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                          <Trash2 size={16}/> Remove
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !ui.sandboxToolsOpen && (
          <button 
            onClick={() => ui.setSandboxToolsOpen(true)} 
            className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"
          >
              <Edit3 size={24} />
          </button>
      )}

      {ui.sandboxToolsOpen && (
          <SandboxTools 
              gameState={gameState}
              setGameState={setGameState}
              sandboxSearchTerm={ui.sandboxSearchTerm}
              setSandboxSearchTerm={ui.setSandboxSearchTerm}
              sandboxTargetPlayer={ui.sandboxTargetPlayer}
              setSandboxTargetPlayer={ui.setSandboxTargetPlayer}
              selectedSandboxCard={ui.selectedSandboxCard}
              setSelectedSandboxCard={ui.setSelectedSandboxCard}
              setSandboxToolsOpen={ui.setSandboxToolsOpen}
              setShowPlaySetup={ui.setShowPlaySetup}
          />
      )}

      {effects.showTurnAnim && (
          <TurnChangeOverlay 
              playerName={gameState.players[gameState.turnPlayer].name}
              turnCount={gameState.turnCount}
              onComplete={() => effects.setShowTurnAnim(false)}
          />
      )}

      {gameState.phase === Phase.GAME_OVER && !tutorialComplete && gameState.mode !== 'TUTORIAL' && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">
                      GAME OVER
                  </h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">
                      {gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!"}
                  </h2>
                  <div className="text-xl text-slate-400 font-title uppercase tracking-widest mt-2">
                      Total Turns: {gameState.turnCount}
                  </div>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      <EndTurnModal show={ui.showEndTurnModal} onCancel={() => ui.setShowEndTurnModal(false)} onConfirm={() => { 
          ui.setShowEndTurnModal(false); 
          performEndTurn(); 
          if(gameState.mode === 'TUTORIAL') advanceTutorialStep('CLICK_UI_BUTTON', 'btn-end-turn-modal-confirm');
      }} />
      <ResignModal show={ui.showResignModal} onCancel={() => ui.setShowResignModal(false)} onConfirm={handleResign} />
      <QuitModal show={ui.showQuitModal} onCancel={() => ui.setShowQuitModal(false)} onConfirm={handleQuitToTitle} />

      <PauseMenu 
        show={ui.showMenu} 
        onResume={() => ui.setShowMenu(false)} 
        onResign={() => ui.setShowResignModal(true)} 
        onQuit={() => ui.setShowQuitModal(true)} 
        autoSort={ui.autoSort} 
        onToggleSort={() => ui.toggleAutoSort(setGameState, getActiveDecisionPlayerId)}
        sfxVolume={ui.sfxVolume}
        setSfxVolume={ui.setSfxVolume}
        musicVolume={ui.musicVolume}
        setMusicVolume={ui.setMusicVolume}
      />

      <DiscardModal 
        viewingDiscard={ui.viewingDiscard} 
        players={gameState.players} 
        onClose={() => ui.setViewingDiscard(null)} 
        mode={gameState.mode} 
      />

      {effects.specialAnim && <SpecialCardAnimation type={effects.specialAnim.type} card={effects.specialAnim.card} targetRect={effects.specialAnim.targetRect} onComplete={() => effects.setSpecialAnim(null)} />}

      {effects.flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {effects.soulTrails.map(st => (
          <SoulOrb key={st.id} trail={st} />
      ))}

      {effects.flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {effects.explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => effects.removeExplosion(e.id)} />
      ))}

      {effects.damageAnims.map(da => (
          <DamageOverlay 
            key={da.id}
            dmg={da.val} 
            targetRef={da.playerId === topPlayer.id ? refs.lifeIconRef : refs.bottomLifeRef}
            onComplete={() => effects.setDamageAnims(prev => prev.filter(a => a.id !== da.id))}
            onImpact={da.onApply}
          />
      ))}

      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId as string);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2} y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2} y2={aRect.top + aRect.height/2}
                        stroke="#3b82f6" strokeWidth="4" strokeDasharray="0" className="opacity-70"
                      />
                  );
              }
              return null;
          })}
          {interactions.dragState?.sourceType === 'FIELD' && interactions.dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(interactions.dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={interactions.dragState.currentX} y2={interactions.dragState.currentY}
                                stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {ui.isMobile ? (
          <MobileLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      ) : (
          <DesktopLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      )}
    </div>
    </>
  );
};

import React, { useState } from 'react';
import { Card, Phase, DragState } from '../types';
import { createFieldCard, canBlock, getEffectiveColor } from '../utils/rules';
import { addLog } from '../utils/core';
import { sortHand } from '../utils/cards';
import { playSound } from '../utils/soundUtils';

export const useGameInteractions = (
    gameState: any, 
    actions: any, 
    effects: any, 
    tutorial: any, 
    ui: any,
    refs: any
) => {
    const [dragState, setDragState] = useState<DragState | null>(null);

    const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string, fromCpu: boolean = false) => {
        const currentState = actions.gameStateRef.current;
        if (!currentState) return;

        const elementId = instanceId || card.id;
        if (currentState.mode === 'TUTORIAL') {
            if (!tutorial.isInteractionAllowed(elementId)) {
                console.log("Tutorial Blocked Interaction:", elementId);
                return;
            }
        }

        if (currentState.mode === 'SANDBOX' && !currentState.isSandboxRun) { 
            ui.setCardActionTarget({ card, loc: location, ownerId, instanceId }); 
            return; 
        }

        const activePlayerId = actions.getActiveDecisionPlayerId(currentState);
        if (!fromCpu && currentState.players[activePlayerId].isCpu && ownerId === activePlayerId) { if (currentState.phase !== Phase.INIT_SELECT) return; }

        if (currentState.phase === Phase.INIT_SELECT && location === 'HAND') {
            if (ownerId === activePlayerId) {
                actions.setGameState((prev: any) => {
                    if(!prev) return null;
                    const isSelected = prev.initSelectedIds.includes(card.id);
                    let newIds = isSelected ? prev.initSelectedIds.filter((id: string) => id !== card.id) : [...prev.initSelectedIds, card.id];
                    if (newIds.length > 3) newIds.pop();
                    return { ...prev, initSelectedIds: newIds };
                });
                if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
            }
        }
        else if (currentState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
            const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
            let cardEl = document.getElementById(card.id); 

            playSound('play_resource');

            if (cardEl && targetResourceContainer) { await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect()); }

            actions.setGameState((prev: any) => {
               if(!prev) return null;
               const p = prev.players[activePlayerId];
               const cardIdx = p.hand.findIndex((c: any) => c.id === card.id);
               const [resCard] = p.hand.splice(cardIdx, 1);
               p.resources.push(createFieldCard(resCard, p.id));
               return { ...prev, phase: Phase.MAIN, logs: addLog(prev, `Converted [${resCard.rank}${resCard.suit}] into a resource.`) };
            });
            await actions.drawCards(activePlayerId, 1);
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
             actions.setGameState((prev: any) => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
             if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
            if (currentState.selectedCardId) {
                // Determine layout logic to find correct hand ref (Bottom vs Top player)
                const isHotseat = !currentState.players[1].isCpu || currentState.mode === 'SANDBOX';
                const viewPlayerId = isHotseat ? activePlayerId : 0;
                const isBottom = activePlayerId === viewPlayerId;

                const handCardEl = document.getElementById(currentState.selectedCardId);
                const resCardEl = instanceId ? document.getElementById(instanceId) : null; 
                const handContainer = isBottom ? refs.handRef.current : refs.cpuHandRef.current;
                const handCard = currentState.players[activePlayerId].hand.find((c: any) => c.id === currentState.selectedCardId);

                if (handCard && handCardEl && resCardEl && handContainer) {
                    const p1 = effects.triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                    const p2 = effects.triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                    await Promise.all([p1, p2]);
                }
            }

            playSound('swap_resource');

            actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const handIdx = p.hand.findIndex((c: any) => c.id === prev.selectedCardId);
                // Note: We match resource by card ID because instance ID might differ in non-tutorial flow, but in this specific block we trust the logic
                const resIdx = p.resources.findIndex((c: any) => c.card.id === card.id);
                if(handIdx > -1 && resIdx > -1) {
                    const handCard = p.hand[handIdx]; const resFieldCard = p.resources[resIdx];

                    const logMsg = `Swapped [${handCard.rank}${handCard.suit}] from hand with [${resFieldCard.card.rank}${resFieldCard.card.suit}] from resources.`;

                    // Create new resource from hand card
                    const newRes = createFieldCard(handCard, p.id);
                    // Force instance ID match in tutorial for consistency if swapping back (edge case)
                    if (prev.mode === 'TUTORIAL') newRes.instanceId = handCard.id;

                    p.hand[handIdx] = resFieldCard.card; 
                    p.resources[resIdx] = newRes; 

                    if(ui.autoSort) p.hand = sortHand(p.hand);
                    return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, logMsg) };
                }
                return { ...prev, selectedCardId: null, phase: Phase.MAIN };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
             actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const fieldCard = p.field.find((fc: any) => fc.instanceId === instanceId);
                if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
                const isAttacking = prev.pendingAttackers.includes(instanceId!);
                const newPending = isAttacking ? prev.pendingAttackers.filter((id: string) => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
                return { ...prev, pendingAttackers: newPending as string[] };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
            if (instanceId && currentState.pendingBlocks[instanceId]) { 
                actions.setGameState((prev: any) => {
                  if(!prev) return null;
                  const newBlocks = { ...prev.pendingBlocks };
                  delete newBlocks[instanceId];
                  return { ...prev, pendingBlocks: newBlocks };
                });
            }
        }
        else if (currentState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
             const player = currentState.players[activePlayerId];
             const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;

             if (untappedRes < card.cost) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
                 return;
             }

             if (['K', 'Q'].includes(card.rank)) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Drag Face Cards to target!") }));
             } else {
                 actions.playCard(card);
                 if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('PLAY_CARD', card.id);
             }
        }
    };

    const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
        if (!gameState) return;
        if (gameState.mode === 'TUTORIAL') {
            const id = instanceId || card.id;
            if (!tutorial.isInteractionAllowed(id)) return;
        }

        if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) {
             setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
             return;
        }
        const activePid = actions.getActiveDecisionPlayerId(gameState);
        if (ownerId !== activePid) return;

        if (gameState.players[activePid].isCpu) return;

        if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
        else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
        else { return; }
        setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
        e.stopPropagation();
    };

    const handleDrop = (e: MouseEvent) => {
        if (!dragState || !gameState) return;
        const elements = document.elementsFromPoint(e.clientX, e.clientY);
        const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');
        if (!targetElement) {
             setDragState(null);
             return;
        }

        if (dragState.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetElement.id === 'field-area' || targetInstanceId) { 
                const player = gameState.players[gameState.turnPlayer];
                const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;
                if (untappedRes < dragState.cardObj.cost) { 
                    actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") })); 
                } else {
                    if (dragState.cardObj.rank === 'Q' || dragState.cardObj.rank === 'K') {
                        if (targetInstanceId) {
                            let targetOwnerId = -1;
                            gameState.players.forEach((p: any) => { if (p.field.some((f: any) => f.instanceId === targetInstanceId)) targetOwnerId = p.id; });
                            if (targetOwnerId !== -1) actions.playCard(dragState.cardObj, targetInstanceId, targetOwnerId);
                        }
                    } else { 
                        actions.playCard(dragState.cardObj); 
                    }
                    if (gameState.mode === 'TUTORIAL') {
                         tutorial.advanceTutorialStep('PLAY_CARD', dragState.cardObj.id);
                    }
                }
            }
        }
        else if (dragState.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetInstanceId && dragState.instanceId) { 
                 const blockerInstanceId = dragState.instanceId;
                 const attackerInstanceId = targetInstanceId;

                 actions.setGameState((prev: any) => {
                    if (!prev) return null;
                    if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;
                    const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
                    const blocker = defP.field.find((f: any) => f.instanceId === blockerInstanceId);
                    const attacker = prev.players[prev.turnPlayer].field.find((f: any) => f.instanceId === attackerInstanceId);
                    if (!blocker || !attacker || blocker.isTapped) return prev;
                    if (!canBlock(attacker, blocker)) return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };

                    let newBlocks = { ...prev.pendingBlocks };

                    // IF Multi-blocking disabled, ensure 1-to-1 by removing any previous block on this attacker
                    const isAlreadyBlocked = Object.values(newBlocks).includes(attackerInstanceId);
                    if (!prev.isMultiBlockingEnabled && isAlreadyBlocked) {
                         // Find and remove the existing blocker for this attacker
                         for (const [key, value] of Object.entries(newBlocks)) {
                             if (value === attackerInstanceId) {
                                 delete newBlocks[key];
                             }
                         }
                    }

                    newBlocks[blockerInstanceId] = attackerInstanceId;
                    return { ...prev, pendingBlocks: newBlocks };
                });

                if (gameState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('DECLARE_BLOCK', blockerInstanceId);
            }
        }
        setDragState(null);
    };

    const handleConfirmInitSelection = async () => {
         const currentState = actions.gameStateRef.current;
         if (!currentState) return;

         const activeId = actions.getActiveDecisionPlayerId(currentState);
         if (currentState.mode === 'TUTORIAL') {
             if (!tutorial.isInteractionAllowed('btn-confirm-init')) return;
             tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-init');
         }

         const p = currentState.players[activeId];
         // Use updated state for selection
         const selectedCards = p.hand.filter((c: any) => currentState.initSelectedIds.includes(c.id));
         const resContainer = document.getElementById(`resource-container-${activeId}`);

         if (resContainer) {
             const resRect = resContainer.getBoundingClientRect();
             // Ensure CPU DOM elements are found. Sometimes the state update for selection runs fast, 
             // but if we are CPU, the cards are rendered.
             const animations = selectedCards.map((c: any) => {
                 let startRect: DOMRect | null = null;
                 const el = document.getElementById(c.id);

                 if (el) {
                     startRect = el.getBoundingClientRect();
                 } else {
                     // Fallback for CPU cards that might be tricky to select (offscreen or reflowed)
                     const handContainer = activeId === 0 ? refs.handRef.current : refs.cpuHandRef.current;
                     if (handContainer) {
                         const parentRect = handContainer.getBoundingClientRect();
                         // Approximate position in center of hand container
                         startRect = {
                             ...parentRect,
                             left: parentRect.left + parentRect.width / 2,
                             top: parentRect.top + parentRect.height / 2,
                             x: parentRect.left + parentRect.width / 2,
                             y: parentRect.top + parentRect.height / 2,
                             width: 0, height: 0, bottom: 0, right: 0, toJSON: () => {}
                         } as DOMRect;
                     }
                 }

                 if (startRect) return effects.triggerFlyer(c, startRect, resRect);
                 return Promise.resolve();
             });
             await Promise.all(animations);
         }

         playSound('play_resource');

         actions.setGameState((prev: any) => {
            if (!prev) return null;
            const p = prev.players[activeId];
            const selected = p.hand.filter((c: any) => prev.initSelectedIds.includes(c.id));
            const remaining = p.hand.filter((c: any) => !prev.initSelectedIds.includes(c.id));
            p.hand = remaining;

            // CRITICAL FIX: Preserve IDs for tutorial resources to allow highlighting
            selected.forEach((c: any) => {
                const fc = createFieldCard(c, p.id);
                if (prev.mode === 'TUTORIAL') fc.instanceId = c.id;
                p.resources.push(fc);
            });

            const otherId = activeId === 0 ? 1 : 0;
            const other = prev.players[otherId];
            let nextState = { ...prev, initSelectedIds: [] };
            let gameStarting = false;

            // Simplified Start Logic: If the other player has resources, start. If not, swap.
            // This works for CPU vs CPU to avoid infinite loops.
            if (other.resources.length >= 3) {
                nextState.logs = addLog(nextState, "Battle Commencing!");
                nextState.phase = Phase.UPKEEP; 
                nextState.turnPlayer = prev.startingPlayerId;
                gameStarting = true;
                setTimeout(() => actions.advancePhase(Phase.UPKEEP, nextState), 500);
            } else {
                nextState.turnPlayer = otherId;
                nextState.logs = addLog(nextState, `${other.name}'s turn to setup.`);
            }

            if (gameStarting) setTimeout(() => effects.setShowTurnAnim(true), 100);
            return nextState;
         });
    };

    const handlePhaseAction = (action: 'ATTACK_PHASE' | 'END_TURN' | 'CONFIRM_ATTACK' | 'CONFIRM_BLOCK' | 'ADD_RESOURCE' | 'SWAP_RESOURCE' | 'CANCEL_RESOURCE' | 'CONFIRM_INIT') => {
        if(action === 'ATTACK_PHASE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-attack-phase')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-attack-phase');
             }
             playSound('attack_phase');
             actions.advancePhase(Phase.ATTACK_DECLARE);
        }
        else if (action === 'END_TURN') {
             if (!tutorial.isInteractionAllowed('btn-end-turn')) return;
             ui.setShowEndTurnModal(true);
             playSound('menu_click');
        }
        else if (action === 'CONFIRM_ATTACK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-attackers')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-attackers');
             }
             actions.confirmAttack();
        }
        else if (action === 'CONFIRM_BLOCK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-blocks') && !tutorial.isInteractionAllowed('btn-tutorial-next')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-blocks');
             }
             actions.confirmBlocks();
        }
        else if (action === 'ADD_RESOURCE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-add-resource')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-add-resource');
             }
             actions.advancePhase(Phase.RESOURCE_ADD_SELECT);
        }
        else if (action === 'SWAP_RESOURCE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-swap-resource')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-swap-resource');
             }
             actions.advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
        }
        else if (action === 'CANCEL_RESOURCE') actions.setGameState((prev: any) => prev ? { ...prev, phase: Phase.RESOURCE_START, selectedCardId: null } : null);
        else if (action === 'CONFIRM_INIT') handleConfirmInitSelection();
    };

    return {
        dragState, setDragState,
        handleCardClick,
        handleDragStart,
        handleDrop,
        handlePhaseAction,
        handleConfirmInitSelection // Exported for AI use
    };
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GameState, Phase, GameMode, PlayerState, Card, FieldCard, Rank, Color, Suit } from '../types';
import { createDeck, createTutorialDeck, sortHand, createTutorialCard } from '../utils/cards';
import { createFieldCard, getEffectiveColor } from '../utils/rules';
import { generateId, addLog, shuffle } from '../utils/core';
import { INITIAL_LIFE, MAX_RESOURCES } from '../constants';
import { TUTORIAL_LESSONS } from '../data/tutorials';
import { playSound } from '../utils/soundUtils';

interface GameStateRefs {
    handRef: React.RefObject<HTMLDivElement>;
    cpuHandRef: React.RefObject<HTMLDivElement>;
    topDeckRef: React.RefObject<HTMLDivElement>;
    bottomDeckRef: React.RefObject<HTMLDivElement>;
    topDiscardRef: React.RefObject<HTMLButtonElement | HTMLDivElement>;
    bottomDiscardRef: React.RefObject<HTMLButtonElement | HTMLDivElement>;
}

interface GameStateProps {
    effects: any; // Using explicit type in real implementation, simplified here for decoupling
    refs: GameStateRefs;
    autoSort: boolean;
}

export const useGameState = ({ effects, refs, autoSort }: GameStateProps) => {
    const [gameState, setGameState] = useState<GameState | null>(null);
    const gameStateRef = useRef<GameState | null>(null);
    const isDrawingInitialRef = useRef(false);

    useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

    const formatCardLog = (card: Card) => `[${card.rank}${card.suit}]`;

    const getActiveDecisionPlayerId = (state: GameState): number => {
        if (state.mode === 'SANDBOX') {
            if (state.isSandboxRun) return state.turnPlayer;
            return state.turnPlayer; 
        }
        if (state.phase === Phase.BLOCK_DECLARE) return state.turnPlayer === 0 ? 1 : 0;
        return state.turnPlayer;
    };

    const startGame = useCallback((mode: GameMode, cpuConfig: { p1: boolean, p2: boolean }, lessonId?: string, isMultiBlockingEnabled?: boolean) => {
        let tutorialConfig = null;
        let initialPhase = mode === 'SANDBOX' ? Phase.MAIN : Phase.INIT_SELECT;
        let startingPlayerId = 0;

        if (mode === 'TUTORIAL' && lessonId) {
            tutorialConfig = TUTORIAL_LESSONS.find(l => l.id === lessonId);
            if (tutorialConfig && tutorialConfig.setup) {
                initialPhase = tutorialConfig.setup.phase || Phase.INIT_SELECT;
                if (tutorialConfig.setup.startingPlayerId !== undefined) {
                    startingPlayerId = tutorialConfig.setup.startingPlayerId;
                }
            }
        }

        let sharedDeck: Card[] = [];
        if (mode === 'STREET') {
            sharedDeck = createDeck();
        } else if (mode === 'TUTORIAL') {
            if (lessonId === 'lesson-3') {
                // Special Deck for Lesson 3: 
                // Exclude all Face Cards and Aces to prevent random tactic draws
                const fullDeck = createDeck();
                const allowedRanks = [Rank.Six, Rank.Seven, Rank.Eight, Rank.Nine, Rank.Ten];
                const riggedDeck = fullDeck.filter(c => allowedRanks.includes(c.rank));
                sharedDeck = shuffle(riggedDeck);
            } else if (lessonId === 'lesson-4') {
                // Special Deck for Lesson 4: J, Q, K stacked on top
                const fullDeck = createDeck();
                // Filter out the specific cards we want to stack so we don't have duplicates
                let remainder = fullDeck.filter(c => 
                    !(c.rank === Rank.Jack && c.suit === Suit.Spades) &&
                    !(c.rank === Rank.Queen && c.suit === Suit.Clubs) &&
                    !(c.rank === Rank.King && c.suit === Suit.Diamonds)
                );
                remainder = shuffle(remainder);
                // Stack specific cards at the beginning (Draw order: Shift from array)
                // We want P1 to draw J first, then Q, then K.
                sharedDeck = [
                    createTutorialCard(Rank.Jack, Suit.Spades),
                    createTutorialCard(Rank.Queen, Suit.Clubs),
                    createTutorialCard(Rank.King, Suit.Diamonds),
                    ...remainder
                ];
            } else {
                sharedDeck = tutorialConfig?.setup ? createDeck() : createTutorialDeck();
            }

            // Filter out cards already used in setup
            if (tutorialConfig?.setup) {
                const usedCards: Card[] = [
                    ...(tutorialConfig.setup.p1Hand || []),
                    ...(tutorialConfig.setup.p1Resources || []),
                    ...(tutorialConfig.setup.p1Field || []),
                    ...(tutorialConfig.setup.p2Hand || []),
                    ...(tutorialConfig.setup.p2Resources || []),
                    ...(tutorialConfig.setup.p2Field || [])
                ];

                sharedDeck = sharedDeck.filter(deckCard => {
                    return !usedCards.some(used => used.rank === deckCard.rank && used.suit === deckCard.suit);
                });
            }
        }

        const createPlayer = (id: number, name: string, isCpu: boolean): PlayerState => {
            let hand: Card[] = [];
            let resources: FieldCard[] = [];
            let field: FieldCard[] = [];
            let life = INITIAL_LIFE;

            if (mode === 'TUTORIAL' && tutorialConfig?.setup) {
                if (id === 0) {
                    hand = tutorialConfig.setup.p1Hand || [];
                    resources = (tutorialConfig.setup.p1Resources || []).map(c => createFieldCard(c, 0));
                    if (tutorialConfig.setup.p1Field) {
                        field = tutorialConfig.setup.p1Field.map(c => {
                            const fc = createFieldCard(c, 0);
                            fc.instanceId = c.id; 
                            fc.isSummoningSick = false;
                            return fc;
                        });
                    }
                    if (tutorialConfig.setup.p1Life) life = tutorialConfig.setup.p1Life;
                } else {
                    hand = tutorialConfig.setup.p2Hand || [];
                    resources = (tutorialConfig.setup.p2Resources || []).map(c => createFieldCard(c, 1));
                    if (tutorialConfig.setup.p2Field) {
                        field = tutorialConfig.setup.p2Field.map(c => {
                            const fc = createFieldCard(c, 1);
                            fc.instanceId = c.id; 
                            fc.isSummoningSick = false;
                            return fc;
                        });
                    }
                    if (tutorialConfig.setup.p2Life) life = tutorialConfig.setup.p2Life;
                }
            }

            return {
                id, name, isCpu, life, hand, 
                library: mode === 'PRO' ? createDeck() : [],
                resources, field, discard: [],
                consecutiveDrawFailures: 0,
                hasAttackedThisTurn: false
            };
        };

        const p1 = createPlayer(0, cpuConfig.p1 ? "CPU 1" : "Player 1", cpuConfig.p1);
        const p2 = createPlayer(1, cpuConfig.p2 ? "CPU 2" : "Player 2", cpuConfig.p2);

        const initialState: GameState = {
            mode,
            isMultiBlockingEnabled: isMultiBlockingEnabled || false,
            deck: sharedDeck,
            players: [p1, p2],
            turnPlayer: initialPhase === Phase.INIT_SELECT ? 0 : startingPlayerId, 
            startingPlayerId: startingPlayerId, 
            phase: initialPhase,
            turnCount: 1,
            pendingAttackers: [],
            pendingBlocks: {},
            selectedCardId: null,
            activeCombatCardId: null,
            initSelectedIds: [],
            targetMode: 'NONE',
            sourceCardId: null,
            winner: null,
            recentDamage: {},
            logs: [{ id: generateId(), text: `Game Started. Mode: ${mode}.` }],
            tutorialState: mode === 'TUTORIAL' && tutorialConfig ? {
                active: true,
                lessonId,
                currentStepIndex: 0,
                steps: tutorialConfig.steps
            } : undefined
        };
        setGameState(initialState);
    }, []);

    const checkGameOver = (state: GameState) => {
        if (state.players[0].life <= 0) state.winner = 1;
        else if (state.players[1].life <= 0) state.winner = 0;

        if (state.winner !== null) {
            state.phase = Phase.GAME_OVER;
            if (state.mode !== 'TUTORIAL') playSound('game_over');
        }
    };

    const resolveTiebreaker = (state: GameState): GameState => {
        const p1 = state.players[0];
        const p2 = state.players[1];

        let reason = "";
        let winner: number | null = null; // null = draw

        // a. Higher Life
        if (p1.life > p2.life) {
            winner = 0;
            reason = "Tiebreaker: Player 1 has higher Life.";
        } else if (p2.life > p1.life) {
            winner = 1;
            reason = "Tiebreaker: Player 2 has higher Life.";
        } else {
            // b. Higher Field Value
            const getFieldValue = (p: PlayerState) => p.field.reduce((acc, f) => acc + (f.card.rank === 'A' ? 1 : f.card.numericValue), 0);
            const val1 = getFieldValue(p1);
            const val2 = getFieldValue(p2);

            if (val1 > val2) {
                winner = 0;
                reason = `Tiebreaker: Life equal. Player 1 has stronger field (${val1} vs ${val2}).`;
            } else if (val2 > val1) {
                winner = 1;
                reason = `Tiebreaker: Life equal. Player 2 has stronger field (${val2} vs ${val1}).`;
            } else {
                // c. Draw
                winner = null; 
                reason = "Tiebreaker: Total Draw (Life & Field Value equal).";
            }
        }

        const nextState = { ...state, phase: Phase.GAME_OVER, logs: addLog(state, reason) };
        if (winner !== null) nextState.winner = winner;

        if (state.mode !== 'TUTORIAL') playSound('game_over');
        return nextState;
    };

    const drawCards = async (playerId: number, count: number) => {
        const startState = gameStateRef.current;
        if (!startState) return;
        const pIndex = startState.players.findIndex(p => p.id === playerId);
        const isSpectate = startState.players[0].isCpu && startState.players[1].isCpu;
        const isHotseat = !startState.players[1].isCpu || startState.players[0].isCpu;
        const viewId = (isHotseat && !isSpectate) ? startState.turnPlayer : 0;
        const isBottom = playerId === viewId;

        const deck = startState.mode === 'STREET' || startState.mode === 'TUTORIAL' ? startState.deck : startState.players[pIndex].library;
        const cardsToDraw = deck.slice(0, Math.min(count, deck.length));
        const failuresNeeded = count - cardsToDraw.length;

        for (const card of cardsToDraw) {
             let startRect = isBottom ? refs.bottomDeckRef.current?.getBoundingClientRect() : refs.topDeckRef.current?.getBoundingClientRect();
             let targetRect = isBottom ? refs.handRef.current?.getBoundingClientRect() : refs.cpuHandRef.current?.getBoundingClientRect();

             if (isSpectate && playerId === 1) {
                 startRect = refs.topDeckRef.current?.getBoundingClientRect();
                 targetRect = refs.cpuHandRef.current?.getBoundingClientRect();
             }

             if (startRect && targetRect) { effects.triggerFlyer(card, startRect, targetRect); }

             playSound('draw');

             setGameState(prev => {
                 if (!prev) return null;
                 const nextPlayers = [...prev.players];
                 const nextP = { ...nextPlayers[pIndex] };
                 let nextDeck = prev.deck;
                 if (prev.mode === 'STREET' || prev.mode === 'TUTORIAL') { nextDeck = prev.deck.filter(c => c.id !== card.id); } 
                 else { nextP.library = nextP.library.filter(c => c.id !== card.id); }
                 nextP.hand = [...nextP.hand, card];
                 // Reset consecutive failure on successful draw
                 nextP.consecutiveDrawFailures = 0;
                 if (autoSort) nextP.hand = sortHand(nextP.hand);
                 nextPlayers[pIndex] = nextP;
                 return { ...prev, deck: prev.mode === 'STREET' || prev.mode === 'TUTORIAL' ? nextDeck : prev.deck, players: nextPlayers };
             });
             await new Promise(r => setTimeout(r, 100)); // Increased slighty for sound pacing
        }
        if (cardsToDraw.length > 0) { setGameState(prev => prev ? { ...prev, logs: addLog(prev, `${startState.players[pIndex].name} drew ${cardsToDraw.length} cards.`) } : null); }

        if (failuresNeeded > 0) {
            setGameState(prev => {
                 if (!prev) return null;
                 const nextPlayers = prev.players.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + failuresNeeded } : pl);
                 const nextState = { ...prev, players: nextPlayers, logs: addLog(prev, `${prev.players[pIndex].name} deck empty!`) };

                 // Tiebreaker Check
                 if (nextPlayers[0].consecutiveDrawFailures > 0 && nextPlayers[1].consecutiveDrawFailures > 0) {
                     return resolveTiebreaker(nextState);
                 }

                 return nextState;
            });
            setTimeout(() => { if (gameStateRef.current) checkGameOver(gameStateRef.current); }, 100);
        }
    };

    const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
        setGameState(prev => {
            if (!prev && !overrideState) return null;
            let newState = overrideState ? { ...overrideState } : { ...prev! };
            newState.phase = targetPhase;
            const player = newState.players[newState.turnPlayer];

            switch (targetPhase) {
                case Phase.UPKEEP:
                    newState.players.forEach(p => {
                        if (p.id === newState.turnPlayer) {
                            p.field.forEach(c => { c.isTapped = false; c.isSummoningSick = false; });
                            p.resources.forEach(r => r.isTapped = false);
                        }
                    });
                    newState.pendingAttackers = []; newState.pendingBlocks = {}; newState.selectedCardId = null; newState.recentDamage = {}; newState.activeCombatCardId = null;
                    player.hasAttackedThisTurn = false;
                    newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
                    playSound('turn_start');
                    setTimeout(() => advancePhase(Phase.DRAW), 800);
                    break;
                case Phase.DRAW:
                    if (newState.mode === 'TUTORIAL') {
                        // Tutorial Mode: Draw logic is sometimes handled by scripts, but default to engine
                        // For Lesson 3 P2 turn, we rely on the engine to draw the card
                    }
                    setTimeout(() => {
                        drawCards(player.id, 1).then(() => {
                            setGameState(current => {
                                if(!current) return null;
                                // Check if game over triggered during draw
                                if (current.phase === Phase.GAME_OVER) return current;

                                const p = current.players[current.turnPlayer];
                                const isTurn1FirstPlayer = current.turnCount === 1 && current.turnPlayer === current.startingPlayerId;
                                const hasMaxResources = p.resources.length >= MAX_RESOURCES;
                                if (isTurn1FirstPlayer || hasMaxResources) {
                                    setTimeout(() => advancePhase(Phase.MAIN), 400);
                                    return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, isTurn1FirstPlayer ? "Turn 1: Resource Step skipped." : "Max Resources reached.") };
                                } else { return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") }; }
                            });
                        });
                    }, 0);
                    break;
                case Phase.RESOURCE_START: break;
                case Phase.MAIN: newState.logs = addLog(newState, "Main Phase."); break;
                case Phase.ATTACK_DECLARE: newState.logs = addLog(newState, "Declare Attackers."); break;
                case Phase.BLOCK_DECLARE:
                    const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
                    newState.logs = addLog(newState, `${defender.name} declares blocks.`);
                    break;
            }
            return newState;
        });
    };

    const playCard = async (card: Card, targetId?: string, targetOwnerId?: number) => {
        let cardIdx = -1; let playedCard: Card | null = null;
        const isFaceCard = ['K', 'Q', 'J'].includes(card.rank);
        const currentState = gameStateRef.current;
        if (!currentState) return;

        if (card.rank === 'K' || card.rank === 'Q') {
            if (!targetId || targetOwnerId === undefined) return;
            const targetP = currentState.players.find(p => p.id === targetOwnerId);
            const targetF = targetP?.field.find(f => f.instanceId === targetId);
            if (!targetF) return; 
            if (card.rank === 'K' && getEffectiveColor(targetF) !== card.baseColor) { 
                setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") }) : null);
                return; 
            }
        }

        // Trigger Sounds
        if (isFaceCard) {
            playSound('tactic');
            if (card.rank === 'K') playSound('king');
            if (card.rank === 'Q') playSound('queen');
        } else {
            if (card.baseColor === Color.Red) playSound('conscript_mag');
            else playSound('conscript_phy');
        }

        if (isFaceCard) {
            let targetRect: DOMRect | undefined;
            if (targetId) { const targetEl = document.getElementById(targetId); if (targetEl) targetRect = targetEl.getBoundingClientRect(); }
            effects.setSpecialAnim({ type: card.rank as 'K'|'Q'|'J', card, targetRect });
            await new Promise(r => setTimeout(r, card.rank === 'K' ? 1200 : card.rank === 'Q' ? 1000 : 800));
            effects.setSpecialAnim(null);
        } else {
            const cardEl = document.getElementById(card.id);
            const fieldEl = document.getElementById('field-area');
            if (cardEl && fieldEl) {
                await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), fieldEl.getBoundingClientRect());
            }
        }

        setGameState(prev => {
            if (!prev) return null;
            const p = prev.players[prev.turnPlayer];
            cardIdx = p.hand.findIndex(c => c.id === card.id);
            if (cardIdx === -1) return prev;
            const newHand = [...p.hand];
            [playedCard] = newHand.splice(cardIdx, 1);
            let toTap = card.cost;
            const newResources = p.resources.map(r => {
                if (!r.isTapped && toTap > 0) { toTap--; return { ...r, isTapped: true }; }
                return r;
            });
            const nextState = { ...prev, players: [...prev.players] };
            const nextPlayer = { ...p, hand: newHand, resources: newResources };
            nextState.players[prev.turnPlayer] = nextPlayer;

            if (card.rank === 'J') { 
                nextPlayer.discard.push(playedCard!); 
                return { ...nextState, logs: addLog(nextState, `Played Jack ${formatCardLog(card)}.`) }; 
            } else if (card.rank === 'K') {
                const targetP = nextState.players[targetOwnerId!];
                const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
                if (targetFIdx === -1) return prev; 
                const targetF = targetP.field[targetFIdx];
                if (getEffectiveColor(targetF) !== card.baseColor) return prev;
                effects.triggerExplosion(targetId!); 
                playSound('destroy');
                effects.triggerScreenShake(4); // Heavy shake for King

                // Trigger Soul Trail for King Kill
                const isSpectate = nextState.players[0].isCpu && nextState.players[1].isCpu;
                const isHotseat = !nextState.players[1].isCpu || nextState.players[0].isCpu;
                const viewId = (isHotseat && !isSpectate) ? nextState.turnPlayer : 0;
                const isTop = targetOwnerId !== viewId;
                const targetRef = isTop ? refs.topDiscardRef : refs.bottomDiscardRef;

                if (targetRef.current && targetId) {
                    const trailColor = getEffectiveColor(targetF) === Color.Red ? 'red' : 'cyan';
                    effects.triggerSoulTrail(targetId, targetRef.current.getBoundingClientRect(), trailColor);
                }

                nextPlayer.discard.push(playedCard!); 
                targetP.field.splice(targetFIdx, 1); 
                targetP.discard.push(targetF.card, ...targetF.attachedCards);
                return { ...nextState, logs: addLog(nextState, `King ${formatCardLog(card)} executed ${formatCardLog(targetF.card)}.`) };
            } else if (card.rank === 'Q') {
                const targetP = nextState.players[targetOwnerId!];
                const targetF = targetP.field.find(f => f.instanceId === targetId);
                if(targetF) {
                    const existingQueens = targetF.attachedCards.filter(c => c.rank === Rank.Queen);
                    if (existingQueens.length > 0) { targetP.discard.push(...existingQueens); targetF.attachedCards = targetF.attachedCards.filter(c => c.rank !== Rank.Queen); }
                    targetF.attachedCards.push(playedCard!);
                }
                return { ...nextState, logs: addLog(nextState, `Queen ${formatCardLog(card)} shifted ${targetF ? formatCardLog(targetF.card) : 'target'}.`) };
            } else {
                const newSoldier = createFieldCard(playedCard!, p.id); 
                if (prev.mode === 'TUTORIAL') {
                    newSoldier.instanceId = card.id;
                }
                nextPlayer.field.push(newSoldier);
                return { ...nextState, logs: addLog(nextState, `Conscripted ${formatCardLog(card)}.`) };
            }
        });

        if (card.rank === 'J' && gameStateRef.current) { await drawCards(gameStateRef.current.turnPlayer, 2); }
    };

    const performEndTurn = () => {
        setGameState(prev => {
            if(!prev) return null;
            if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2') {
                if (prev.turnPlayer === 0) {
                    const nextPlayers = [...prev.players];
                    const p2 = { ...nextPlayers[1] };
                    p2.field = p2.field.map(f => {
                        if (f.instanceId === 'tut-5-♥') return { ...f, isTapped: true };
                        return f;
                    });
                    nextPlayers[1] = p2;
                    const nextState = { ...prev, players: nextPlayers, turnPlayer: 1, phase: Phase.BLOCK_DECLARE }; 
                    nextState.pendingAttackers = ['tut-5-♥'];
                    nextState.logs = addLog(nextState, "CPU 2 attacks with [5♥].");
                    return nextState;
                } else if (prev.turnPlayer === 1) {
                    const nextPlayers = prev.players.map(p => ({
                        ...p,
                        hasAttackedThisTurn: false,
                        field: p.id === 0 ? p.field.map(f => ({...f, isTapped: false, isSummoningSick: false})) : p.field,
                        resources: p.id === 0 ? p.resources.map(r => ({...r, isTapped: false})) : p.resources
                    }));
                    const nextState = { ...prev, players: nextPlayers, turnPlayer: 0, turnCount: prev.turnCount + 1, phase: Phase.MAIN, logs: addLog(prev, "Your Turn.") };
                    return nextState;
                }
            }
            const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
            const nextTurnCount = nextPlayerIdx === prev.startingPlayerId ? prev.turnCount + 1 : prev.turnCount;
            const nextState = { ...prev, turnPlayer: nextPlayerIdx, turnCount: nextTurnCount, phase: Phase.UPKEEP };
            setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
            return nextState; 
        });
        effects.setShowTurnAnim(true);
    };

    const confirmAttack = () => {
        // Play tap sound if attackers are declared
        if (gameStateRef.current && gameStateRef.current.pendingAttackers.length > 0) {
            playSound('draw');
        }

        setGameState(prev => {
            if(!prev) return null;
            if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2' && prev.turnPlayer === 0 && prev.phase === Phase.ATTACK_DECLARE) {
                if (prev.turnCount > 1) {
                    const p = prev.players[0];
                    const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
                    const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
                    p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
                    p.hasAttackedThisTurn = true;
                    return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
                }
                const blocks: Record<string, string> = {};
                blocks['tut-2-♠'] = 'tut-2-♣';
                const p = prev.players[0];
                const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
                const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
                p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
                p.hasAttackedThisTurn = true;
                return { ...prev, pendingBlocks: blocks, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
            }
            if (prev.pendingAttackers.length === 0) return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
            const p = prev.players[prev.turnPlayer];
            const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
            const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
            p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
            p.hasAttackedThisTurn = true;
            const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
            const attackingColors = new Set(attackers.map(getEffectiveColor));
            const untappedDefenders = defender.field.filter(f => !f.isTapped);
            const canDefend = untappedDefenders.some(def => attackingColors.has(getEffectiveColor(def)));
            if (!canDefend) return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
            return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
        });
    };

    const confirmBlocks = () => { setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null); };

    // Resolve Combat Loop
    useEffect(() => { 
        if (gameState?.phase === Phase.DAMAGE) {
            (async () => {
                const state = gameStateRef.current!;
                const attackerPlayer = state.players[state.turnPlayer];
                const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
                const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

                // Attackers that have NO blockers targeting them
                const directAttackers = attackers.filter(atk => !Object.values(state.pendingBlocks).includes(atk.instanceId));

                // Helper to trigger death effects
                const handleCardDeath = (cardInstanceId: string, ownerId: number) => {
                    const isHotseat = !state.players[1].isCpu || state.mode === 'SANDBOX';
                    const viewId = (isHotseat) ? state.turnPlayer : 0;
                    const isTop = ownerId !== viewId;

                    const targetRef = isTop ? refs.topDiscardRef : refs.bottomDiscardRef;
                    const dyingCard = state.players.find(p => p.id === ownerId)?.field.find(f => f.instanceId === cardInstanceId);

                    if (targetRef.current && dyingCard) {
                        const trailColor = getEffectiveColor(dyingCard) === Color.Red ? 'red' : 'cyan';
                        effects.triggerSoulTrail(cardInstanceId, targetRef.current.getBoundingClientRect(), trailColor);
                    }
                    effects.triggerExplosion(cardInstanceId);
                };

                // Blocked Combats Loop
                // Note: Logic updated to support Multi-Blocking if enabled, but works for single blocking too.
                const blockedAttackers = attackers.filter(atk => Object.values(state.pendingBlocks).includes(atk.instanceId));

                for (const atk of blockedAttackers) {
                    // Find all blockers for this attacker
                    const blockerIds = Object.keys(state.pendingBlocks).filter(k => state.pendingBlocks[k] === atk.instanceId);
                    const blockers = defenderPlayer.field.filter(f => blockerIds.includes(f.instanceId));

                    if (blockers.length > 0) {
                        // Play animations sequentially for each blocker
                        for (const blk of blockers) {
                            setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
                            playSound('menu_click'); // Lunge sound

                            await new Promise(r => setTimeout(r, 400));
                            setGameState(prev => {
                                if (!prev) return null;
                                const nextRecentDamage = { ...prev.recentDamage };
                                // Show "damage taken" visually
                                nextRecentDamage[atk.instanceId] = (nextRecentDamage[atk.instanceId] || 0) + blk.card.numericValue;
                                nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                                const logMsg = `⚔️ Battle: ${formatCardLog(atk.card)} vs ${formatCardLog(blk.card)}`;
                                return { ...prev, recentDamage: nextRecentDamage, logs: addLog(prev, logMsg) };
                            });
                            await new Promise(r => setTimeout(r, 600)); 
                            setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                            await new Promise(r => setTimeout(r, 100));
                        }
                    }
                }

                // Direct Attacks Loop
                for (const atk of directAttackers) {
                    setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);

                    // Shake Intensity for direct attacks
                    const shakeIntensity = atk.card.rank === 'A' ? 1 : Math.min(4, Math.ceil(atk.card.numericValue / 2.5));
                    effects.triggerScreenShake(shakeIntensity);

                    const val = atk.card.numericValue;
                    if (val <= 4 || atk.card.rank === 'A') playSound('damage_sm');
                    else if (val <= 7) playSound('damage_md');
                    else playSound('damage_lg');

                    await new Promise(r => setTimeout(r, 200));
                    const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;

                    const applyDamage = () => {
                        setGameState(prev => {
                            if (!prev) return null;
                            const nextPlayers = [...prev.players];
                            const defIdx = nextPlayers.findIndex(p => p.id === defenderPlayer.id);
                            if (defIdx > -1) { 
                                nextPlayers[defIdx] = { ...nextPlayers[defIdx], life: Math.max(0, nextPlayers[defIdx].life - dmg) }; 
                            }
                            let nextState = { ...prev, players: nextPlayers };
                            return nextState;
                        });
                    };
                    effects.addDamageAnim(dmg, defenderPlayer.id, applyDamage);

                    setGameState(prev => prev ? { ...prev, logs: addLog(prev, `🔥 Direct Hit! ${formatCardLog(atk.card)} deals ${dmg} damage.`) } : null);
                    // Wait longer than animation (1200ms) to ensure impact happens before next loop or cleanup
                    await new Promise(r => setTimeout(r, 1250)); 
                    setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                }

                // Cleanup Phase - SEQUENTIAL ANIMATION
                // Re-fetch state because life totals might have changed during direct attacks
                const finalState = gameStateRef.current!;
                const activeAtkIds = finalState.pendingAttackers;
                const dyingData: { instanceId: string, ownerId: number }[] = [];

                // 1. Identify Deaths (Read-Only)
                // We calculate accumulated damage here.
                const fAtkP = finalState.players[finalState.turnPlayer];
                const fDefP = finalState.players[finalState.turnPlayer === 0 ? 1 : 0];

                // Get all attackers that were involved in combat this turn
                const activeAtk = fAtkP.field.filter(f => activeAtkIds.includes(f.instanceId));

                for (const atk of activeAtk) {
                     // Find all blockers for this attacker
                     const blockerIds = Object.keys(finalState.pendingBlocks).filter(k => finalState.pendingBlocks[k] === atk.instanceId);
                     const blockers = fDefP.field.filter(f => blockerIds.includes(f.instanceId));

                     if (blockers.length > 0) {
                         const atkVal = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                         const atkIsAce = atk.card.rank === 'A';
                         let accumulatedDamageToAtk = 0;
                         let anyBlockerIsAce = false;

                         // Calculate outcomes for each blocker
                         for (const blk of blockers) {
                             const blkVal = blk.card.rank === 'A' ? 1 : blk.card.numericValue;
                             const blkIsAce = blk.card.rank === 'A';

                             if (blkIsAce) anyBlockerIsAce = true;
                             accumulatedDamageToAtk += blkVal;

                             // Does Blocker die?
                             // Blocker dies if Attacker is Ace OR Attacker Value >= Blocker Value
                             let blkDies = false;
                             if (atkIsAce) blkDies = true;
                             else if (atkVal >= blkVal) blkDies = true; // Tie or Win for Attacker kills Blocker
                             // Note: Standard rules say "Higher value wins". Ties = both die.
                             // 7 vs 4. 7 kills 4. 4 deals 4 to 7.
                             // 4 vs 4. Both die.
                             // So yes, if atkVal >= blkVal, blkDies.

                             if (blkDies) {
                                 // Check if already marked (unlikely in this loop but good practice)
                                 if (!dyingData.some(d => d.instanceId === blk.instanceId)) {
                                     dyingData.push({ instanceId: blk.instanceId, ownerId: fDefP.id });
                                 }
                             }
                         }

                         // Does Attacker die?
                         // Attacker dies if any blocker is Ace OR Accumulated Damage >= Attacker Value
                         // Special logic for Ace Attacker: It has 1 HP. So if it takes ANY damage (>=1), it dies.
                         // Accumulated damage >= 1 for Ace means it dies, which fits the logic.
                         if (anyBlockerIsAce || accumulatedDamageToAtk >= atkVal) {
                             if (!dyingData.some(d => d.instanceId === atk.instanceId)) {
                                 dyingData.push({ instanceId: atk.instanceId, ownerId: fAtkP.id });
                             }
                         }
                     }
                }

                // 2. Trigger Animations Staggered AND REMOVE CARDS IMMEDIATELY
                if (dyingData.length > 0) {
                    for (const d of dyingData) {
                        handleCardDeath(d.instanceId, d.ownerId); // Visual Effect
                        playSound('destroy');

                        // Immediately remove the specific card to sync with explosion
                        setGameState(prev => {
                            if (!prev) return null;
                            const nextState = { ...prev };
                            const nextPlayers = [...nextState.players];

                            const pIndex = nextPlayers.findIndex(p => p.id === d.ownerId);
                            if (pIndex > -1) {
                                const p = { ...nextPlayers[pIndex] };
                                const fIndex = p.field.findIndex(f => f.instanceId === d.instanceId);
                                if (fIndex > -1) {
                                    const [dead] = p.field.splice(fIndex, 1);
                                    p.discard = [...p.discard, dead.card, ...dead.attachedCards];
                                    nextPlayers[pIndex] = p;
                                }
                            }

                            return { ...nextState, players: nextPlayers };
                        });

                        await new Promise(r => setTimeout(r, 200)); // Stagger delay
                    }
                    // Wait a little extra for the last explosion/soul trail to traverse
                    await new Promise(r => setTimeout(r, 600));
                }

                // 3. Final State Update (Phase change, clear pending)
                setGameState(prev => {
                    if (!prev) return null;
                    const nextState = { ...prev };

                    nextState.recentDamage = {}; 
                    nextState.pendingAttackers = []; 
                    nextState.pendingBlocks = {}; 
                    nextState.phase = Phase.MAIN;

                    // Game Over Check (re-check with latest life totals)
                    if (nextState.players[0].life <= 0) nextState.winner = 1;
                    else if (nextState.players[1].life <= 0) nextState.winner = 0;

                    if (nextState.winner !== null) {
                        nextState.phase = Phase.GAME_OVER;
                        if (nextState.mode !== 'TUTORIAL') playSound('game_over');
                    }
                    return nextState;
                });

            })();
        }
    }, [gameState?.phase]);

    return {
        gameState, setGameState, gameStateRef,
        startGame,
        drawCards,
        playCard,
        advancePhase,
        performEndTurn,
        confirmAttack,
        confirmBlocks,
        isDrawingInitialRef,
        getActiveDecisionPlayerId
    };
};

import { Card, FieldCard, PlayerState, GameState, Rank, Color } from '../types';
import { MAX_RESOURCES } from '../constants';
import { getEffectiveColor, canBlock } from './rules';

// Helper function for scoring cards to decide what to keep/resource
const getKeepScore = (c: Card, currentRes: number) => {
    if (c.rank === Rank.Ace) return 200; // Must Keep (Wild + Cheap)

    // Always try to keep Tactics
    if (['K', 'Q', 'J'].includes(c.rank)) return 90; 

    // High priority: Units we can play NOW or Next Turn
    if (c.cost <= currentRes) return 110; 
    if (c.cost === currentRes + 1) return 80;

    // Low priority: Expensive units. 
    // We add numericValue to score so we prefer keeping bigger threats if costs are equal.
    // e.g. Cost 8 vs Cost 9. Both score low (~30), but we keep the 9.
    return 20 + c.numericValue; 
};

export const getCpuInitSelection = (hand: Card[]): string[] => {
    // We want to resource cards that are:
    // 1. Not Aces (Wilds are valuable) - Score 100
    // 2. Not Face Cards (Tactics are valuable) - Score 90
    // 3. Not low cost soldiers (Need early game board presence) - Score 80
    // So we prefer to resource High Cost Soldiers (6, 7, 8, 9, 10) first (Score 0).

    const getResourcePreference = (c: Card) => {
        if (c.rank === Rank.Ace) return 100; // KEEP
        if (['K', 'Q', 'J'].includes(c.rank)) return 90; // KEEP
        if (c.numericValue <= 4) return 80; // KEEP (Early plays)
        // 5, 6, 7, 8, 9, 10 -> These are good resource candidates
        // Higher value = Better soldier, but harder to cast.
        // We prefer resourcing the middle-high stuff.
        return 0; // Resource these
    };

    const sorted = [...hand].sort((a, b) => getResourcePreference(a) - getResourcePreference(b));

    // Pick the 3 with the lowest preference (i.e., the best to throw away as resources)
    return sorted.slice(0, 3).map(c => c.id);
};

export const getCpuResourceDecision = (cpu: PlayerState, turnCount: number): { 
    action: 'ADD' | 'SWAP' | 'SKIP', 
    cardIdToAdd?: string,
    cardIdToSwapHand?: string,
    resourceInstanceIdToSwap?: string
} => {
    const currentRes = cpu.resources.length;

    // Calculate keep scores for hand
    const scoredHand = cpu.hand.map(c => ({ c, score: getKeepScore(c, currentRes) }));
    // Sort Ascending: Lowest score (worst card) first
    scoredHand.sort((a, b) => {
        if (a.score !== b.score) return a.score - b.score;
        return a.c.numericValue - b.c.numericValue;
    });

    const worstHandCard = scoredHand[0];

    // DECISION: Should we SWAP?
    // Check swap first to see if there's huge value
    const scoredResources = cpu.resources.map(r => ({ r, score: getKeepScore(r.card, currentRes) }));
    scoredResources.sort((a, b) => b.score - a.score); // Highest score (best card) first

    const bestResource = scoredResources[0];

    // Determine Swap Threshold based on game stage
    // Early game (low resources): High threshold to discourage swapping (we need to RAMP)
    // Late game (high resources): Low threshold to encourage filtering before maxing out
    let swapThreshold = 40;
    if (currentRes < 5) {
        swapThreshold = 80; // RAMP MODE: Only swap if getting something insanely better (e.g. Ace for a 2)
    } else if (currentRes < 8) {
        swapThreshold = 50; // MID GAME
    } else if (currentRes >= 9) {
        swapThreshold = 10; // LATE GAME: Filter aggressively before locking at 10
    }

    if (bestResource && worstHandCard) {
        if (bestResource.score > worstHandCard.score + swapThreshold) {
            return { 
                action: 'SWAP', 
                cardIdToSwapHand: worstHandCard.c.id, 
                resourceInstanceIdToSwap: bestResource.r.instanceId 
            };
        }
    }

    // DECISION: Should we ADD a resource?
    // Logic update: CPU MUST add if < 10 resources, unless swapping.
    if (currentRes < MAX_RESOURCES && worstHandCard) {
        return { action: 'ADD', cardIdToAdd: worstHandCard.c.id };
    }

    return { action: 'SKIP' };
};

export const getBestMainPhaseAction = (gameState: GameState): { type: 'PLAY_UNIT' | 'PLAY_TACTIC' | 'END_TURN', cardId?: string, targetId?: string } => {
    const cpu = gameState.players[gameState.turnPlayer];
    const opponent = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];
    const availableResources = cpu.resources.filter(r => !r.isTapped).length;
    const playable = cpu.hand.filter(c => c.cost <= availableResources);

    if (playable.length === 0) return { type: 'END_TURN' };

    // 1. TACTICS (Priority)
    // King: Use if we have a valid target
    const kings = playable.filter(c => c.rank === Rank.King);
    for (const king of kings) {
        // Target highest value opponent in matching lane
        const targets = opponent.field.filter(f => getEffectiveColor(f) === king.baseColor);
        targets.sort((a, b) => b.card.numericValue - a.card.numericValue);

        // UPDATE: CPU should not waste Kings on weak units unless desperate
        if (targets.length > 0) {
            const bestTarget = targets[0];
            // Only Execute if target is worth it (Value >= 7) OR if CPU is low on life and target is moderate threat
            const isWorthIt = bestTarget.card.numericValue >= 7 || (cpu.life <= 10 && bestTarget.card.numericValue >= 5);

            if (isWorthIt) {
                return { type: 'PLAY_TACTIC', cardId: king.id, targetId: bestTarget.instanceId };
            }
        }
    }

    // Queen: Strategy -> Shift a unit's color.
    const queens = playable.filter(c => c.rank === Rank.Queen);
    let bestQueenPlay: { cardId: string, targetId: string, score: number } | null = null;

    for (const queen of queens) {
        const qColor = queen.baseColor;

        // 1. Evaluate Enemy Targets (Disrupt defense or mitigate offense)
        const enemyTargets = opponent.field.filter(f => getEffectiveColor(f) !== qColor);
        for (const t of enemyTargets) {
            let score = 0;
            const tVal = t.card.numericValue;

            // A. Offensive Value: Is this enemy blocking my big units?
            // My units in target's CURRENT color
            const myAttackersCurrent = cpu.field.filter(f => !f.isTapped && !f.isSummoningSick && getEffectiveColor(f) === getEffectiveColor(t));
            // If I have a big attacker here, moving the blocker is good.
            const blockedAttacker = myAttackersCurrent.sort((a,b) => b.card.numericValue - a.card.numericValue)[0];
            if (blockedAttacker && blockedAttacker.card.numericValue >= tVal) {
                score += 40; // Remove blocker
                if (blockedAttacker.card.numericValue > tVal) score += 10; // Save my unit from trade
            }

            // B. Defensive Value: Is this enemy threatening me, and can I block it if I move it?
            // Do I have blockers in the NEW color?
            const myBlockersNew = cpu.field.filter(f => !f.isTapped && getEffectiveColor(f) === qColor);
            const bestBlocker = myBlockersNew.sort((a,b) => b.card.numericValue - a.card.numericValue)[0];

            // Do I LACK blockers in the OLD color?
            const myBlockersOld = cpu.field.filter(f => !f.isTapped && getEffectiveColor(f) === getEffectiveColor(t));

            if (myBlockersOld.length === 0 && myBlockersNew.length > 0) {
                // Moving unblocked threat to blocked lane
                score += 50;
                if (bestBlocker && bestBlocker.card.numericValue > tVal) score += 20; // Favorable trade
            } else if (myBlockersOld.length === 0 && myBlockersNew.length === 0) {
                // Moving unblocked threat to... still unblocked lane.
                score -= 50; 
            }

            if (score > 30) {
                if (!bestQueenPlay || score > bestQueenPlay.score) {
                    bestQueenPlay = { cardId: queen.id, targetId: t.instanceId, score };
                }
            }
        }

        // 2. Evaluate Self Targets (Fix bad matchups)
        const selfTargets = cpu.field.filter(f => getEffectiveColor(f) !== qColor);
        for (const t of selfTargets) {
            let score = 0;
            const tVal = t.card.numericValue;

            // A. Offense: Am I blocked? Will I be unblocked?
            const enemyBlockersOld = opponent.field.filter(f => !f.isTapped && getEffectiveColor(f) === getEffectiveColor(t));
            const enemyBlockersNew = opponent.field.filter(f => !f.isTapped && getEffectiveColor(f) === qColor);

            const biggestBlockerOld = enemyBlockersOld.sort((a,b) => b.card.numericValue - a.card.numericValue)[0];
            const biggestBlockerNew = enemyBlockersNew.sort((a,b) => b.card.numericValue - a.card.numericValue)[0];

            // If I am currently blocked by a bigger/equal unit
            if (biggestBlockerOld && biggestBlockerOld.card.numericValue >= tVal) {
                // And in new lane, I am unblocked OR blocked by smaller unit
                if (!biggestBlockerNew) {
                    score += 50; // Free hit!
                } else if (biggestBlockerNew.card.numericValue < tVal) {
                    score += 40; // Favorable trade
                }
            } else if (!biggestBlockerOld) {
                // Currently unblocked. Moving to unblocked is neutral. Moving to blocked is bad.
                if (biggestBlockerNew) score -= 30;
            }

            // B. Defense: Do I need to block something in the new lane?
            const enemyThreatsNew = opponent.field.filter(f => !f.isTapped && getEffectiveColor(f) === qColor); // Potential attackers
            // If there is an unblocked threat in new lane that I can handle
            if (enemyThreatsNew.length > 0) {
                 const bigThreat = enemyThreatsNew.sort((a,b) => b.card.numericValue - a.card.numericValue)[0];
                 // If I move there, can I kill it or trade?
                 if (tVal >= bigThreat.card.numericValue) {
                     score += 30; // Move to intercept
                 }
            }

            if (score > 30) {
                if (!bestQueenPlay || score > bestQueenPlay.score) {
                    bestQueenPlay = { cardId: queen.id, targetId: t.instanceId, score };
                }
            }
        }
    }

    if (bestQueenPlay) {
        return { type: 'PLAY_TACTIC', cardId: bestQueenPlay.cardId, targetId: bestQueenPlay.targetId };
    }

    // Jack: Play for draw
    const jacks = playable.filter(c => c.rank === Rank.Jack);
    if (jacks.length > 0) return { type: 'PLAY_TACTIC', cardId: jacks[0].id };

    // 2. UNITS
    const units = playable.filter(c => !['J', 'Q', 'K'].includes(c.rank));
    if (units.length === 0) return { type: 'END_TURN' };

    // Sort units by value high to low
    units.sort((a, b) => b.numericValue - a.numericValue);
    const bigUnit = units[0];

    // STRATEGY: Go Wide vs Go Big
    const boardDisadvantage = Math.max(0, opponent.field.length - cpu.field.length);
    const smallUnits = units.slice(1).sort((a, b) => a.cost - b.cost); // Cheapest first
    const widePlay: Card[] = [];
    let currentCost = 0;

    for (const u of smallUnits) {
        if (currentCost + u.cost <= availableResources) {
            widePlay.push(u);
            currentCost += u.cost;
        }
    }

    if (widePlay.length > 1) {
        const bigVal = bigUnit.numericValue;
        const wideVal = widePlay.reduce((sum, c) => sum + c.numericValue, 0);
        const wideBonus = boardDisadvantage * 3; // Value board presence more if behind

        if (wideVal + wideBonus >= bigVal) {
             return { type: 'PLAY_UNIT', cardId: widePlay[0].id };
        }
    }

    return { type: 'PLAY_UNIT', cardId: bigUnit.id };
};

export const getCpuAttackers = (gameState: GameState): string[] => {
    const cpu = gameState.players[gameState.turnPlayer];
    const opponent = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];
    const potential = cpu.field.filter(f => !f.isTapped && !f.isSummoningSick);
    const blockers = opponent.field.filter(f => !f.isTapped);

    // --- LETHAL CHECK (Checkmate Logic) ---
    // If attacking with everything results in a win, do it. Ignore safety.
    const getPotentialDamage = (attackers: FieldCard[], currentBlockers: FieldCard[]) => {
        const redAtk = attackers.filter(c => getEffectiveColor(c) === Color.Red).map(c => c.card.rank === 'A' ? 1 : c.card.numericValue).sort((a,b) => b-a);
        const blackAtk = attackers.filter(c => getEffectiveColor(c) === Color.Black).map(c => c.card.rank === 'A' ? 1 : c.card.numericValue).sort((a,b) => b-a);

        const redBlkCount = currentBlockers.filter(c => getEffectiveColor(c) === Color.Red).length;
        const blackBlkCount = currentBlockers.filter(c => getEffectiveColor(c) === Color.Black).length;

        // Remove damage that gets blocked (Highest damage sources are blocked first by rational opponent)
        const unblockedRed = redAtk.slice(redBlkCount);
        const unblockedBlack = blackAtk.slice(blackBlkCount);

        return [...unblockedRed, ...unblockedBlack].reduce((sum, val) => sum + val, 0);
    };

    if (getPotentialDamage(potential, blockers) >= opponent.life) {
        return potential.map(c => c.instanceId);
    }

    // 1. Identify desirable attacks (Greedy Phase)
    let candidates: FieldCard[] = [];

    for (const atk of potential) {
        const atkColor = getEffectiveColor(atk);
        const validBlockers = blockers.filter(b => getEffectiveColor(b) === atkColor);

        if (validBlockers.length === 0) {
            candidates.push(atk); continue;
        }

        const freeKill = validBlockers.some(b => b.card.numericValue > atk.card.numericValue && b.card.rank !== 'A' && atk.card.rank !== 'A');
        if (freeKill) continue; 

        const equalTrade = validBlockers.some(b => 
            (b.card.numericValue === atk.card.numericValue) || 
            (b.card.rank === 'A' && atk.card.rank !== 'A') || 
            (atk.card.rank === 'A' && b.card.rank !== 'A')
        );

        if (equalTrade) {
            // Aggressive or desperate
            if (atk.card.numericValue <= 8 || cpu.life < 10) {
                candidates.push(atk);
            }
            continue;
        }

        // We win combat
        candidates.push(atk);
    }

    // 2. Safety Check: Ensure we don't die on crackback
    // Identify Threats: All opponent units (untapped + tapped, as they will untap next turn)
    const threats = opponent.field; 

    // Simulation function to check damage leaking through
    const calculatePredictedDamage = (myBlockers: FieldCard[]) => {
        const blackBlockers = myBlockers.filter(b => getEffectiveColor(b) === Color.Black).length;
        const redBlockers = myBlockers.filter(b => getEffectiveColor(b) === Color.Red).length;

        // Calculate max incoming damage assuming opponent attacks with everything
        const blackThreats = threats.filter(t => getEffectiveColor(t) === Color.Black).map(t => t.card.rank === 'A' ? 1 : t.card.numericValue).sort((a,b) => b-a);
        const redThreats = threats.filter(t => getEffectiveColor(t) === Color.Red).map(t => t.card.rank === 'A' ? 1 : t.card.numericValue).sort((a,b) => b-a);

        let dmg = 0;
        if (blackThreats.length > blackBlockers) {
            dmg += blackThreats.slice(blackBlockers).reduce((a, b) => a + b, 0);
        }
        if (redThreats.length > redBlockers) {
            dmg += redThreats.slice(redBlockers).reduce((a, b) => a + b, 0);
        }
        return dmg;
    };

    let predictedDamage = calculatePredictedDamage(cpu.field.filter(f => !candidates.includes(f)));

    // If danger, pull back attackers
    // Limit loop to prevent infinite (though candidates shrinks, so it's finite)
    while (predictedDamage >= cpu.life && candidates.length > 0) {
        const currentBlockers = cpu.field.filter(f => !candidates.includes(f));
        const blackBlockers = currentBlockers.filter(b => getEffectiveColor(b) === Color.Black).length;
        const redBlockers = currentBlockers.filter(b => getEffectiveColor(b) === Color.Red).length;

        const blackThreats = threats.filter(t => getEffectiveColor(t) === Color.Black).length;
        const redThreats = threats.filter(t => getEffectiveColor(t) === Color.Red).length;

        const needBlack = blackThreats > blackBlockers;
        const needRed = redThreats > redBlockers;

        // Sort candidates: We want to pull back the WEAKEST attacker that can block
        // Actually, we want to pull back the one that contributes least to offense but helps defense.
        // For simplicity, pull back lowest numeric value.
        candidates.sort((a, b) => a.card.numericValue - b.card.numericValue);

        let pulled = false;

        // Try to pull a candidate that helps the color we are leaking
        if (needBlack) {
            const idx = candidates.findIndex(c => getEffectiveColor(c) === Color.Black);
            if (idx !== -1) {
                candidates.splice(idx, 1);
                pulled = true;
            }
        }

        if (!pulled && needRed) {
            const idx = candidates.findIndex(c => getEffectiveColor(c) === Color.Red);
            if (idx !== -1) {
                candidates.splice(idx, 1);
                pulled = true;
            }
        }

        if (!pulled) {
             // Mismatch, remaining candidates can't help with defense colors.
             // Just break to preserve whatever offense we have.
             break;
        }

        predictedDamage = calculatePredictedDamage(cpu.field.filter(f => !candidates.includes(f)));
    }

    return candidates.map(c => c.instanceId);
};

// Helper: Find best combination of blockers to kill a target with minimized cost
const findMultiBlockCombination = (targetVal: number, blockers: FieldCard[]): FieldCard[] | null => {
    let bestCombination: FieldCard[] | null = null;
    let bestSum = Infinity;

    // Basic recursive subset sum search
    const search = (index: number, currentSum: number, currentCards: FieldCard[]) => {
        // Pruning: if current sum already exceeds best found sum, stop (we want min cost)
        if (currentSum >= bestSum) return;

        // Success: we killed it
        if (currentSum >= targetVal) {
            bestSum = currentSum;
            bestCombination = [...currentCards];
            return;
        }

        // Run out of cards
        if (index >= blockers.length) return;

        // Include card at index
        const card = blockers[index];
        const val = card.card.rank === 'A' ? 1 : card.card.numericValue;

        search(index + 1, currentSum + val, [...currentCards, card]);

        // Exclude card at index
        search(index + 1, currentSum, currentCards);
    };

    // Sort blockers by value descending to potentially hit target faster in DFS?
    // Actually, heuristic sort isn't strictly necessary for small N, but helps.
    search(0, 0, []);
    return bestCombination;
};

export const getCpuBlocks = (gameState: GameState, defendingPlayerId: number): Record<string, string> => {
    const blocks: Record<string, string> = {};
    const cpu = gameState.players[defendingPlayerId];
    const opponent = gameState.players[defendingPlayerId === 0 ? 1 : 0];
    const attackerIds = gameState.pendingAttackers;

    const attackers = opponent.field.filter(f => attackerIds.includes(f.instanceId));
    const myBlockers = cpu.field.filter(f => !f.isTapped);
    const usedBlockers = new Set<string>();

    // Sort attackers high to low (Prioritize blocking biggest threats)
    attackers.sort((a, b) => b.card.numericValue - a.card.numericValue);

    // Calculate Potential Damage for Lethal Check
    let potentialDamage = 0;
    for(const atk of attackers) {
        potentialDamage += (atk.card.rank === Rank.Ace ? 1 : atk.card.numericValue);
    }
    const isLethal = potentialDamage >= cpu.life;

    for (const atk of attackers) {
        const validBlockers = myBlockers.filter(b => !usedBlockers.has(b.instanceId) && canBlock(atk, b));

        if (validBlockers.length > 0) {
            let chosen: FieldCard[] = [];

            // --- 1. SINGLE BLOCK STRATEGY ---
            // A. Kill Attacker (Blocker > Atk)
            const killer = validBlockers.find(b => b.card.numericValue > atk.card.numericValue && b.card.rank !== 'A');

            // B. Trade Equal (Blocker == Atk)
            const trader = !killer ? validBlockers.find(b => b.card.numericValue === atk.card.numericValue) : undefined;

            // C. Trade Up (Blocker < Atk, but Blocker is Ace)
            const aceTrader = (!killer && !trader && atk.card.rank !== 'A') 
                ? validBlockers.find(b => b.card.rank === 'A') 
                : undefined;

            if (killer) chosen = [killer];
            else if (trader) chosen = [trader];
            else if (aceTrader) chosen = [aceTrader];

            // --- 2. MULTI-BLOCK STRATEGY (If enabled & no single good block found) ---
            if (chosen.length === 0 && gameState.isMultiBlockingEnabled) {
                // We couldn't single block effectively. Can we gang up?
                const atkVal = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                const combo = findMultiBlockCombination(atkVal, validBlockers);

                if (combo) {
                    const comboCost = combo.reduce((sum, c) => sum + (c.card.rank === 'A' ? 1 : c.card.numericValue), 0);

                    // Evaluate Trade:
                    // We lose all blockers involved (Cost). We kill Attacker (Value).
                    // Accept if Cost <= Attacker Value (Fair Trade) OR if we are about to die.
                    // Note: We count Ace blocker as value 1 here, but Ace blocker would have been picked by single block logic usually.

                    if (isLethal || comboCost <= atkVal) {
                        chosen = combo;
                    }
                }
            }

            // --- 3. CHUMP BLOCK STRATEGY (Last Resort) ---
            // If we still haven't picked a block, but we are dying or taking huge damage...
            if (chosen.length === 0) {
                validBlockers.sort((a, b) => a.card.numericValue - b.card.numericValue);
                const weakest = validBlockers[0];

                const damageIfUnblocked = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                const valueLost = weakest.card.rank === 'A' ? 10 : weakest.card.numericValue; 

                let blockThreshold = 4;
                if (cpu.life < 10) blockThreshold = 2;
                if (isLethal) blockThreshold = -999; // Block everything if lethal

                if ((damageIfUnblocked - valueLost) >= blockThreshold) {
                    chosen = [weakest];
                }
            }

            // Apply Blocks
            if (chosen.length > 0) {
                for (const b of chosen) {
                    blocks[b.instanceId] = atk.instanceId;
                    usedBlockers.add(b.instanceId);
                }
            }
        }
    }
    return blocks;
};

import React from 'react';
import { Card, Suit, Color, Rank } from '../types';

interface CardDisplayProps extends React.HTMLAttributes<HTMLDivElement> {
  card: Card;
  domId?: string;
  onClick?: () => void;
  onMouseDown?: (e: React.MouseEvent) => void;
  onTouchStart?: (e: React.TouchEvent) => void; // Added Touch Handler
  isSelected?: boolean;
  isTapped?: boolean;
  isSummoningSick?: boolean; // New Prop
  isPlayable?: boolean;
  isTargetable?: boolean;
  isAttacking?: boolean;
  isLunging?: boolean;
  isDragging?: boolean;
  isBlocking?: boolean;
  attachedCards?: Card[];
  damageTaken?: number;
  size?: 'sm' | 'md' | 'lg';
  showBack?: boolean;
  orientation?: 'top' | 'bottom';
}

export const CardDisplay: React.FC<CardDisplayProps> = ({
  card,
  domId,
  onClick,
  onMouseDown,
  onTouchStart,
  isSelected,
  isTapped,
  isSummoningSick,
  isPlayable,
  isTargetable,
  isAttacking,
  isLunging,
  isDragging,
  isBlocking,
  attachedCards,
  damageTaken,
  size = 'md',
  showBack = false,
  orientation = 'bottom',
  ...rest
}) => {
  // Determine effective color based on attached Queen
  const attachedQueen = attachedCards?.find(c => c.rank === Rank.Queen);
  const effectiveColor = attachedQueen ? attachedQueen.baseColor : card.baseColor;
  const isRed = effectiveColor === Color.Red;

  // Size classes
  const dimensions = {
    sm: 'w-12 h-16 text-xs rounded-sm',
    md: 'w-20 h-28 text-sm rounded',
    lg: 'w-32 h-44 text-lg rounded-md',
  };

  // Lunging animation logic
  const lungeClass = isLunging
    ? (orientation === 'bottom' ? '-translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600' : 'translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600')
    : '';

  // Tooltip Logic
  const showCostTooltip = [Rank.Ace, Rank.Jack, Rank.Queen, Rank.King].includes(card.rank);
  const cost = card.rank === Rank.Ace ? 1 : card.rank === Rank.Jack ? 2 : card.rank === Rank.Queen ? 3 : 4;

  if (showBack) {
    return (
      <div
        id={domId}
        className={`${dimensions[size]} bg-indigo-900 border-2 border-slate-200 shadow-md relative overflow-hidden flex items-center justify-center`}
        {...rest}
      >
        <div className="w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-700 to-indigo-950 opacity-80"></div>
        <div className="absolute text-indigo-300 font-title font-bold opacity-30">BATTLE</div>
      </div>
    );
  }

  return (
    <div className="relative group">
      {/* Attached Cards (Queens) - Rendered BEHIND the main card wrapper */}
      {attachedCards && attachedCards.length > 0 && (
          <div className="absolute inset-0 pointer-events-none z-0">
              {attachedCards.map((ac, idx) => {
                  const isQueenRed = ac.baseColor === Color.Red;
                  return (
                    <div 
                        key={ac.id} 
                        className={`absolute -top-3 left-1/2 -translate-x-1/2 w-[90%] h-8 rounded-t-lg border-x border-t shadow-sm flex items-start justify-center pt-0.5
                            ${isQueenRed ? 'bg-red-100 border-red-300' : 'bg-slate-200 border-slate-400'}
                        `}
                        style={{ transform: `translateX(-50%) translateY(${idx * -4}px) scale(0.95)` }}
                    >
                        <span className={`text-[0.6rem] font-bold ${isQueenRed ? 'text-red-700' : 'text-slate-800'}`}>
                            {ac.rank}{ac.suit}
                        </span>
                    </div>
                  );
              })}
          </div>
      )}

      {/* Main Card */}
      <div
        id={domId}
        onClick={onClick}
        onMouseDown={onMouseDown}
        onTouchStart={onTouchStart}
        className={`
          ${dimensions[size]} 
          relative z-10
          bg-white shadow-md select-none transition-all duration-300 ease-out
          flex flex-col justify-between p-1
          ${isRed ? 'text-red-600' : 'text-slate-900'}
          ${isSelected ? 'ring-4 ring-yellow-400 -translate-y-2 z-20' : 'border border-slate-300'}
          ${isPlayable ? 'ring-2 ring-green-400 cursor-grab active:cursor-grabbing hover:-translate-y-1' : ''}
          ${isTargetable ? 'ring-4 ring-red-500 cursor-crosshair animate-pulse' : ''}
          ${isTapped ? 'rotate-90 opacity-70' : ''}
          ${isAttacking && !isLunging ? 'ring-4 ring-red-600 -translate-y-6 shadow-xl z-20' : ''} 
          ${isBlocking ? 'ring-4 ring-blue-500 -translate-y-4 shadow-lg' : ''}
          ${isDragging ? 'opacity-50 grayscale' : ''}
          ${lungeClass}
          ${onClick || onMouseDown || onTouchStart ? 'cursor-pointer' : ''}
          ${onMouseDown || onTouchStart ? 'touch-none' : ''} 
        `}
        {...rest}
      >
        {/* Summoning Sickness Indicator */}
        {isSummoningSick && !isTapped && (
            <div className="absolute top-1 right-1 z-30 animate-pulse">
                <div className="text-slate-400 font-bold bg-white/90 rounded-full px-1 text-[0.6rem] border border-slate-300 shadow-sm leading-none pb-0.5">
                    zZ
                </div>
            </div>
        )}

        {/* Top Corner (Self Start) */}
        <div className="flex flex-col items-center leading-none z-0 self-start">
          <span className="font-bold font-title">{card.rank}</span>
          <span className="text-[0.8em]">{card.suit}</span>
        </div>

        {/* Center Art */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20 z-0">
          <span className="text-4xl">{card.suit}</span>
        </div>

        {/* Bottom Corner (Self End) */}
        <div className="flex flex-col items-center leading-none rotate-180 z-0 self-end">
          <span className="font-bold font-title">{card.rank}</span>
          <span className="text-[0.8em]">{card.suit}</span>
        </div>

        {/* Special Badges */}
        {card.rank === 'A' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-black text-white text-[0.5rem] px-1 rounded uppercase tracking-tighter z-10">
            Wild
          </div>
        )}
        {['J', 'Q', 'K'].includes(card.rank) && (
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-[0.5rem] uppercase font-bold tracking-widest bg-slate-100 px-1 rounded shadow-sm opacity-80 z-10">
            {card.rank === 'J' ? 'Draw 2' : card.rank === 'Q' ? 'Shift' : 'Kill'}
          </div>
        )}

        {/* Damage Popup */}
        {damageTaken !== undefined && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[60] pointer-events-none animate-bounce scale-150">
              <div className="text-4xl font-black text-white stroke-black drop-shadow-[0_4px_4px_rgba(0,0,0,1)]" style={{ WebkitTextStroke: '1px black' }}>
                  -{damageTaken}
              </div>
          </div>
        )}

        {/* Cost Tooltip on Hover */}
        {showCostTooltip && isPlayable && (
            <div className="absolute -top-10 left-1/2 -translate-x-1/2 hidden group-hover:flex flex-col items-center z-[100] animate-in fade-in zoom-in duration-200">
                <div className="bg-slate-900 text-white text-xs font-bold px-2 py-1 rounded shadow-lg whitespace-nowrap border border-slate-700">
                    Cost: {cost}
                </div>
                <div className="w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[4px] border-t-slate-900"></div>
            </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { GameState, PlayerState, Card, DragState, Phase } from '../../types';

export interface GameHandlers {
    onCardClick: (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => void;
    onDragStart: (e: React.MouseEvent | React.TouchEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => void;
    onPhaseAction: (action: 'ATTACK_PHASE' | 'END_TURN' | 'CONFIRM_ATTACK' | 'CONFIRM_BLOCK' | 'ADD_RESOURCE' | 'SWAP_RESOURCE' | 'CANCEL_RESOURCE' | 'CONFIRM_INIT') => void;
    setViewingDiscard: (view: 'SHARED' | number | null) => void;
    setShowMenu: (show: boolean) => void;
    toggleLog?: () => void;
}

export interface GameRefs {
    handRef: React.RefObject<HTMLDivElement>;
    cpuHandRef: React.RefObject<HTMLDivElement>;
    topDeckRef: React.RefObject<HTMLDivElement>;
    bottomDeckRef: React.RefObject<HTMLDivElement>;
    lifeIconRef: React.RefObject<HTMLDivElement>;
    bottomLifeRef: React.RefObject<HTMLDivElement>;
    topDiscardRef: React.RefObject<HTMLButtonElement | HTMLDivElement>;
    bottomDiscardRef: React.RefObject<HTMLButtonElement | HTMLDivElement>;
}

export interface LayoutProps {
    gameState: GameState;
    topPlayer: PlayerState;
    bottomPlayer: PlayerState;
    activeDecisionPlayerId: number;
    isInteractive: boolean;
    dragState: DragState | null;
    handlers: GameHandlers;
    refs: GameRefs;
    uiState: {
        showMobileLog: boolean;
        showMenu: boolean;
    };
}

import React, { useState } from 'react';
import { Card, Phase, DragState } from '../types';
import { createFieldCard, canBlock, getEffectiveColor } from '../utils/rules';
import { addLog } from '../utils/core';
import { sortHand } from '../utils/cards';
import { playSound } from '../utils/soundUtils';

export const useGameInteractions = (
    gameState: any, 
    actions: any, 
    effects: any, 
    tutorial: any, 
    ui: any,
    refs: any
) => {
    const [dragState, setDragState] = useState<DragState | null>(null);

    const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string, fromCpu: boolean = false) => {
        const currentState = actions.gameStateRef.current;
        if (!currentState) return;

        const elementId = instanceId || card.id;
        if (currentState.mode === 'TUTORIAL') {
            if (!tutorial.isInteractionAllowed(elementId)) {
                console.log("Tutorial Blocked Interaction:", elementId);
                return;
            }
        }

        if (currentState.mode === 'SANDBOX' && !currentState.isSandboxRun) { 
            ui.setCardActionTarget({ card, loc: location, ownerId, instanceId }); 
            return; 
        }

        const activePlayerId = actions.getActiveDecisionPlayerId(currentState);
        if (!fromCpu && currentState.players[activePlayerId].isCpu && ownerId === activePlayerId) { if (currentState.phase !== Phase.INIT_SELECT) return; }

        if (currentState.phase === Phase.INIT_SELECT && location === 'HAND') {
            if (ownerId === activePlayerId) {
                actions.setGameState((prev: any) => {
                    if(!prev) return null;
                    const isSelected = prev.initSelectedIds.includes(card.id);
                    let newIds = isSelected ? prev.initSelectedIds.filter((id: string) => id !== card.id) : [...prev.initSelectedIds, card.id];
                    if (newIds.length > 3) newIds.pop();
                    return { ...prev, initSelectedIds: newIds };
                });
                if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
            }
        }
        else if (currentState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
            const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
            let cardEl = document.getElementById(card.id); 

            playSound('play_resource');

            if (cardEl && targetResourceContainer) { await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect()); }

            actions.setGameState((prev: any) => {
               if(!prev) return null;
               const p = prev.players[activePlayerId];
               const cardIdx = p.hand.findIndex((c: any) => c.id === card.id);
               const [resCard] = p.hand.splice(cardIdx, 1);
               p.resources.push(createFieldCard(resCard, p.id));
               return { ...prev, phase: Phase.MAIN, logs: addLog(prev, `Converted [${resCard.rank}${resCard.suit}] into a resource.`) };
            });
            await actions.drawCards(activePlayerId, 1);
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
             actions.setGameState((prev: any) => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
             if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
            if (currentState.selectedCardId) {
                // Determine layout logic to find correct hand ref (Bottom vs Top player)
                const isHotseat = !currentState.players[1].isCpu || currentState.mode === 'SANDBOX';
                const viewPlayerId = isHotseat ? activePlayerId : 0;
                const isBottom = activePlayerId === viewPlayerId;

                const handCardEl = document.getElementById(currentState.selectedCardId);
                const resCardEl = instanceId ? document.getElementById(instanceId) : null; 
                const handContainer = isBottom ? refs.handRef.current : refs.cpuHandRef.current;
                const handCard = currentState.players[activePlayerId].hand.find((c: any) => c.id === currentState.selectedCardId);

                if (handCard && handCardEl && resCardEl && handContainer) {
                    const p1 = effects.triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                    const p2 = effects.triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                    await Promise.all([p1, p2]);
                }
            }

            playSound('swap_resource');

            actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const handIdx = p.hand.findIndex((c: any) => c.id === prev.selectedCardId);
                // Note: We match resource by card ID because instance ID might differ in non-tutorial flow, but in this specific block we trust the logic
                const resIdx = p.resources.findIndex((c: any) => c.card.id === card.id);
                if(handIdx > -1 && resIdx > -1) {
                    const handCard = p.hand[handIdx]; const resFieldCard = p.resources[resIdx];

                    const logMsg = `Swapped [${handCard.rank}${handCard.suit}] from hand with [${resFieldCard.card.rank}${resFieldCard.card.suit}] from resources.`;

                    // Create new resource from hand card
                    const newRes = createFieldCard(handCard, p.id);
                    // Force instance ID match in tutorial for consistency if swapping back (edge case)
                    if (prev.mode === 'TUTORIAL') newRes.instanceId = handCard.id;

                    p.hand[handIdx] = resFieldCard.card; 
                    p.resources[resIdx] = newRes; 

                    if(ui.autoSort) p.hand = sortHand(p.hand);
                    return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, logMsg) };
                }
                return { ...prev, selectedCardId: null, phase: Phase.MAIN };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
             actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const fieldCard = p.field.find((fc: any) => fc.instanceId === instanceId);
                if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
                const isAttacking = prev.pendingAttackers.includes(instanceId!);
                const newPending = isAttacking ? prev.pendingAttackers.filter((id: string) => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
                return { ...prev, pendingAttackers: newPending as string[] };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
            if (instanceId && currentState.pendingBlocks[instanceId]) { 
                actions.setGameState((prev: any) => {
                  if(!prev) return null;
                  const newBlocks = { ...prev.pendingBlocks };
                  delete newBlocks[instanceId];
                  return { ...prev, pendingBlocks: newBlocks };
                });
            }
        }
        else if (currentState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
             const player = currentState.players[activePlayerId];
             const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;

             if (untappedRes < card.cost) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
                 return;
             }

             if (['K', 'Q'].includes(card.rank)) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Drag Face Cards to target!") }));
             } else {
                 actions.playCard(card);
                 if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('PLAY_CARD', card.id);
             }
        }
    };

    const handleDragStart = (e: React.MouseEvent | React.TouchEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
        if (!gameState) return;
        if (gameState.mode === 'TUTORIAL') {
            const id = instanceId || card.id;
            if (!tutorial.isInteractionAllowed(id)) return;
        }

        if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) {
             let clientX, clientY;
             if ('touches' in e) {
                 clientX = e.touches[0].clientX;
                 clientY = e.touches[0].clientY;
             } else {
                 clientX = (e as React.MouseEvent).clientX;
                 clientY = (e as React.MouseEvent).clientY;
             }
             setDragState({ cardId: card.id, sourceType: type, ownerId, startX: clientX, startY: clientY, currentX: clientX, currentY: clientY, cardObj: card, instanceId });
             return;
        }
        const activePid = actions.getActiveDecisionPlayerId(gameState);
        if (ownerId !== activePid) return;

        if (gameState.players[activePid].isCpu) return;

        if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
        else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
        else { return; }

        let clientX, clientY;
        if ('touches' in e) {
            clientX = e.touches[0].clientX;
            clientY = e.touches[0].clientY;
        } else {
            clientX = (e as React.MouseEvent).clientX;
            clientY = (e as React.MouseEvent).clientY;
        }

        setDragState({ cardId: card.id, sourceType: type, ownerId, startX: clientX, startY: clientY, currentX: clientX, currentY: clientY, cardObj: card, instanceId });
        e.stopPropagation();
    };

    const handleDrop = (e: MouseEvent | TouchEvent | React.TouchEvent | React.MouseEvent) => {
        if (!dragState || !gameState) return;

        let clientX: number, clientY: number;

        // Handle Native and React events
        if ('changedTouches' in e && e.changedTouches.length > 0) {
             // TouchEvent (Native or React)
             clientX = e.changedTouches[0].clientX;
             clientY = e.changedTouches[0].clientY;
        } else if ('clientX' in e) {
             // MouseEvent
             clientX = (e as MouseEvent).clientX;
             clientY = (e as MouseEvent).clientY;
        } else {
            return;
        }

        const elements = document.elementsFromPoint(clientX, clientY);
        const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');
        if (!targetElement) {
             setDragState(null);
             return;
        }

        if (dragState.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetElement.id === 'field-area' || targetInstanceId) { 
                const player = gameState.players[gameState.turnPlayer];
                const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;
                if (untappedRes < dragState.cardObj.cost) { 
                    actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") })); 
                } else {
                    if (dragState.cardObj.rank === 'Q' || dragState.cardObj.rank === 'K') {
                        if (targetInstanceId) {
                            let targetOwnerId = -1;
                            gameState.players.forEach((p: any) => { if (p.field.some((f: any) => f.instanceId === targetInstanceId)) targetOwnerId = p.id; });
                            if (targetOwnerId !== -1) actions.playCard(dragState.cardObj, targetInstanceId, targetOwnerId);
                        }
                    } else { 
                        actions.playCard(dragState.cardObj); 
                    }
                    if (gameState.mode === 'TUTORIAL') {
                         tutorial.advanceTutorialStep('PLAY_CARD', dragState.cardObj.id);
                    }
                }
            }
        }
        else if (dragState.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetInstanceId && dragState.instanceId) { 
                 const blockerInstanceId = dragState.instanceId;
                 const attackerInstanceId = targetInstanceId;

                 actions.setGameState((prev: any) => {
                    if (!prev) return null;
                    if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;
                    const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
                    const blocker = defP.field.find((f: any) => f.instanceId === blockerInstanceId);
                    const attacker = prev.players[prev.turnPlayer].field.find((f: any) => f.instanceId === attackerInstanceId);
                    if (!blocker || !attacker || blocker.isTapped) return prev;
                    if (!canBlock(attacker, blocker)) return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };

                    let newBlocks = { ...prev.pendingBlocks };

                    // IF Multi-blocking disabled, ensure 1-to-1 by removing any previous block on this attacker
                    const isAlreadyBlocked = Object.values(newBlocks).includes(attackerInstanceId);
                    if (!prev.isMultiBlockingEnabled && isAlreadyBlocked) {
                         // Find and remove the existing blocker for this attacker
                         for (const [key, value] of Object.entries(newBlocks)) {
                             if (value === attackerInstanceId) {
                                 delete newBlocks[key];
                             }
                         }
                    }

                    newBlocks[blockerInstanceId] = attackerInstanceId;
                    return { ...prev, pendingBlocks: newBlocks };
                });

                if (gameState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('DECLARE_BLOCK', blockerInstanceId);
            }
        }
        setDragState(null);
    };

    const handleConfirmInitSelection = async () => {
         const currentState = actions.gameStateRef.current;
         if (!currentState) return;

         const activeId = actions.getActiveDecisionPlayerId(currentState);
         if (currentState.mode === 'TUTORIAL') {
             if (!tutorial.isInteractionAllowed('btn-confirm-init')) return;
             tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-init');
         }

         const p = currentState.players[activeId];
         // Use updated state for selection
         const selectedCards = p.hand.filter((c: any) => currentState.initSelectedIds.includes(c.id));
         const resContainer = document.getElementById(`resource-container-${activeId}`);

         if (resContainer) {
             const resRect = resContainer.getBoundingClientRect();
             // Ensure CPU DOM elements are found. Sometimes the state update for selection runs fast, 
             // but if we are CPU, the cards are rendered.
             const animations = selectedCards.map((c: any) => {
                 let startRect: DOMRect | null = null;
                 const el = document.getElementById(c.id);

                 if (el) {
                     startRect = el.getBoundingClientRect();
                 } else {
                     // Fallback for CPU cards that might be tricky to select (offscreen or reflowed)
                     const handContainer = activeId === 0 ? refs.handRef.current : refs.cpuHandRef.current;
                     if (handContainer) {
                         const parentRect = handContainer.getBoundingClientRect();
                         // Approximate position in center of hand container
                         startRect = {
                             ...parentRect,
                             left: parentRect.left + parentRect.width / 2,
                             top: parentRect.top + parentRect.height / 2,
                             x: parentRect.left + parentRect.width / 2,
                             y: parentRect.top + parentRect.height / 2,
                             width: 0, height: 0, bottom: 0, right: 0, toJSON: () => {}
                         } as DOMRect;
                     }
                 }

                 if (startRect) return effects.triggerFlyer(c, startRect, resRect);
                 return Promise.resolve();
             });
             await Promise.all(animations);
         }

         playSound('play_resource');

         actions.setGameState((prev: any) => {
            if (!prev) return null;
            const p = prev.players[activeId];
            const selected = p.hand.filter((c: any) => prev.initSelectedIds.includes(c.id));
            const remaining = p.hand.filter((c: any) => !prev.initSelectedIds.includes(c.id));
            p.hand = remaining;

            // CRITICAL FIX: Preserve IDs for tutorial resources to allow highlighting
            selected.forEach((c: any) => {
                const fc = createFieldCard(c, p.id);
                if (prev.mode === 'TUTORIAL') fc.instanceId = c.id;
                p.resources.push(fc);
            });

            const otherId = activeId === 0 ? 1 : 0;
            const other = prev.players[otherId];
            let nextState = { ...prev, initSelectedIds: [] };
            let gameStarting = false;

            // Simplified Start Logic: If the other player has resources, start. If not, swap.
            // This works for CPU vs CPU to avoid infinite loops.
            if (other.resources.length >= 3) {
                nextState.logs = addLog(nextState, "Battle Commencing!");
                nextState.phase = Phase.UPKEEP; 
                nextState.turnPlayer = prev.startingPlayerId;
                gameStarting = true;
                setTimeout(() => actions.advancePhase(Phase.UPKEEP, nextState), 500);
            } else {
                nextState.turnPlayer = otherId;
                nextState.logs = addLog(nextState, `${other.name}'s turn to setup.`);
            }

            if (gameStarting) setTimeout(() => effects.setShowTurnAnim(true), 100);
            return nextState;
         });
    };

    const handlePhaseAction = (action: 'ATTACK_PHASE' | 'END_TURN' | 'CONFIRM_ATTACK' | 'CONFIRM_BLOCK' | 'ADD_RESOURCE' | 'SWAP_RESOURCE' | 'CANCEL_RESOURCE' | 'CONFIRM_INIT') => {
        if(action === 'ATTACK_PHASE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-attack-phase')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-attack-phase');
             }
             playSound('attack_phase');
             actions.advancePhase(Phase.ATTACK_DECLARE);
        }
        else if (action === 'END_TURN') {
             if (!tutorial.isInteractionAllowed('btn-end-turn')) return;
             ui.setShowEndTurnModal(true);
             playSound('menu_click');
        }
        else if (action === 'CONFIRM_ATTACK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-attackers')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-attackers');
             }
             actions.confirmAttack();
        }
        else if (action === 'CONFIRM_BLOCK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-blocks') && !tutorial.isInteractionAllowed('btn-tutorial-next')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-blocks');
             }
             actions.confirmBlocks();
        }
        else if (action === 'ADD_RESOURCE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-add-resource')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-add-resource');
             }
             actions.advancePhase(Phase.RESOURCE_ADD_SELECT);
        }
        else if (action === 'SWAP_RESOURCE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-swap-resource')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-swap-resource');
             }
             actions.advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
        }
        else if (action === 'CANCEL_RESOURCE') actions.setGameState((prev: any) => prev ? { ...prev, phase: Phase.RESOURCE_START, selectedCardId: null } : null);
        else if (action === 'CONFIRM_INIT') handleConfirmInitSelection();
    };

    return {
        dragState, setDragState,
        handleCardClick,
        handleDragStart,
        handleDrop,
        handlePhaseAction,
        handleConfirmInitSelection // Exported for AI use
    };
};

import React, { useEffect, useState } from 'react';
import { Phase, GameMode } from './types';
import { addLog } from './utils/core';
import { createFieldCard } from './utils/rules';
import { RotateCcw, Play, Edit3, Trash2, GraduationCap, Volume2 } from 'lucide-react';
