import React, { useState, useLayoutEffect, useEffect, useRef } from 'react';
import { CardDisplay } from '../CardDisplay';
import { Card, FlyingCard, Rank, SoulTrail, SummoningCard, Color } from '../../types';

export const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(0.6) rotate(0deg)',
        transition: 'transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useEffect(() => {
        const centerX = window.innerWidth / 2 - 40; // 40 = half of w-20 (80px)
        const centerY = window.innerHeight / 2 - 56; // 56 = half of h-28 (112px)
        const targetDX = fc.targetX - fc.startX;
        const targetDY = fc.targetY - fc.startY;

        let timeout1: number, timeout2: number;

        if (fc.pauseDuration && fc.pauseDuration > 0) {
            // STEP 1: Move to Center
            requestAnimationFrame(() => {
                setStyle(prev => ({
                    ...prev,
                    left: centerX, 
                    top: centerY,
                    transform: 'scale(1.5) rotate(360deg)', 
                    transition: 'all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
                }));
            });

            // STEP 2: Wait then Move to Target
            timeout1 = setTimeout(() => {
                setStyle(prev => ({
                    ...prev,
                    left: fc.targetX,
                    top: fc.targetY,
                    transform: 'scale(0.8) rotate(0deg)', // Approx hand scale
                    transition: 'all 0.5s ease-in-out'
                }));
            }, 500 + fc.pauseDuration); // Fly time + pause

            // Finish
            timeout2 = setTimeout(() => {
                if (fc.onComplete) fc.onComplete();
            }, 500 + fc.pauseDuration + 500);

        } else {
            // Standard Direct Flight
            requestAnimationFrame(() => {
                setStyle(prev => ({
                    ...prev,
                    transform: `translate(${targetDX}px, ${targetDY}px) scale(0.6) rotate(360deg)`
                }));
            });

            timeout1 = setTimeout(() => {
                if (fc.onComplete) fc.onComplete();
            }, 600);
        }

        return () => {
            clearTimeout(timeout1);
            clearTimeout(timeout2);
        };
    }, []);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={!fc.showFace} size="md" />
        </div>
    );
};

export const Summoner: React.FC<{ sc: SummoningCard }> = ({ sc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: sc.startX,
        top: sc.startY,
        position: 'fixed',
        zIndex: 200,
        transform: 'translate(-50%, -50%) scale(0.8) rotate(0deg)',
        transition: 'all 0.4s ease-out',
        pointerEvents: 'none',
        opacity: 1
    });

    const [phase, setPhase] = useState<'LIFT' | 'HOVER' | 'SLAM'>('LIFT');

    useEffect(() => {
        // Calculate Target Coordinates using exact element ID
        const targetEl = document.getElementById(sc.targetElementId);
        let targetX = window.innerWidth / 2;
        let targetY = window.innerHeight / 2;

        if (targetEl) {
            const rect = targetEl.getBoundingClientRect();
            targetX = rect.left + rect.width / 2;
            targetY = rect.top + rect.height / 2;
        }

        // Phase 1: Lift & Reveal (Immediate)
        // We move it to slightly above the target zone, larger scale
        const isRed = sc.card.baseColor === Color.Red;
        const liftY = targetY + (sc.ownerId === 0 ? 50 : -50); // Slightly offset from lane center towards player

        requestAnimationFrame(() => {
            setStyle({
                left: targetX,
                top: liftY,
                position: 'fixed',
                zIndex: 300,
                transform: 'translate(-50%, -50%) scale(1.4) rotate(0deg)',
                transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)', // Spring out
                pointerEvents: 'none',
                boxShadow: isRed ? '0 0 30px rgba(220, 38, 38, 0.6)' : '0 0 30px rgba(99, 102, 241, 0.6)'
            });
        });

        // Phase 2: Hover (Pause for recognition)
        const hoverTimer = setTimeout(() => {
            setPhase('HOVER');
        }, 400);

        // Phase 3: Slam (Down to board)
        const slamTimer = setTimeout(() => {
            setPhase('SLAM');
            setStyle(prev => ({
                ...prev,
                left: targetX,
                top: targetY, // Precise lane center
                transform: 'translate(-50%, -50%) scale(1.0)',
                transition: 'all 0.2s cubic-bezier(0.6, -0.28, 0.735, 0.045)', // Hard impact ease
                zIndex: 200
            }));
        }, 900); // 400ms lift + 500ms hover

        // Complete
        const doneTimer = setTimeout(() => {
            if (sc.onComplete) sc.onComplete();
        }, 1150); // 900 + 250ms slam

        return () => {
            clearTimeout(hoverTimer);
            clearTimeout(slamTimer);
            clearTimeout(doneTimer);
        };
    }, []);

    return (
        <div style={style}>
            <CardDisplay card={sc.card} showBack={false} size="md" />
            {phase === 'SLAM' && (
                <div className="absolute inset-0 -m-8 z-[-1] animate-ping opacity-50 bg-white rounded-full" />
            )}
        </div>
    );
};

export const SoulOrb: React.FC<{ trail: SoulTrail }> = ({ trail }) => {
    // Calculate angle ONCE at start so it doesn't spin during flight
    const dx = trail.targetX - trail.startX;
    const dy = trail.targetY - trail.startY;
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);

    const [style, setStyle] = useState<React.CSSProperties>({
        left: trail.startX,
        top: trail.startY,
        position: 'fixed',
        width: '48px',
        height: '48px',
        zIndex: 200,
        // Set initial rotation immediately
        transform: `translate(-50%, -50%) rotate(${angle}deg) scale(1)`,
        opacity: 1,
        // Animate position and scale/opacity, but rotation stays fixed (via the transform string)
        transition: 'left 0.8s ease-in, top 0.8s ease-in, opacity 0.8s ease-in, transform 0.8s ease-in',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                left: trail.targetX,
                top: trail.targetY,
                opacity: 0,
                // Maintain angle, shrink scale
                transform: `translate(-50%, -50%) rotate(${angle}deg) scale(0.2)`
            }));
        });
    }, [trail, angle]);

    const isRed = trail.color === 'red';
    const glowColor = isRed ? '#dc2626' : '#2563eb'; // Deep Red or Blue
    const coreColor = isRed ? '#fca5a5' : '#93c5fd'; // Light Red or Blue
    const trailColor = isRed ? 'rgba(239, 68, 68, 0.8)' : 'rgba(59, 130, 246, 0.8)';

    return (
        <div style={style}>
            {/* The Orb Core */}
            <div 
                className="absolute inset-0 rounded-full z-10"
                style={{
                    backgroundColor: 'white',
                    boxShadow: `0 0 20px 5px ${glowColor}, inset 0 0 10px ${glowColor}`
                }}
            />

            {/* The Inner Core Glow */}
            <div 
                className="absolute inset-2 rounded-full z-20 animate-pulse"
                style={{ backgroundColor: coreColor }}
            />

            {/* The Trail */}
            <div 
                className="absolute right-1/2 top-1/2 origin-right rounded-l-full z-0"
                style={{
                    width: '200px',
                    height: '40px',
                    transform: 'translateY(-50%) translateX(20px)', // Push slightly into the head
                    background: `linear-gradient(to left, ${trailColor} 0%, transparent 100%)`,
                    filter: 'blur(8px)',
                }}
            />
            {/* Secondary Trail for Intensity */}
            <div 
                className="absolute right-1/2 top-1/2 origin-right rounded-l-full z-0"
                style={{
                    width: '100px',
                    height: '20px',
                    transform: 'translateY(-50%) translateX(10px)',
                    background: `linear-gradient(to left, white 0%, transparent 100%)`,
                    filter: 'blur(4px)',
                    opacity: 0.6
                }}
            />
        </div>
    );
};

export const SpecialCardAnimation: React.FC<{ type: 'K' | 'Q' | 'J', card: Card, targetRect?: DOMRect, onComplete: () => void }> = ({ type, card, targetRect, onComplete }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        position: 'fixed',
        left: '50%',
        top: '50%',
        transform: 'translate(-50%, -50%) scale(0.5)',
        opacity: 0,
        zIndex: 200,
        transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
    });

    const [label, setLabel] = useState("");
    const [colorClass, setColorClass] = useState("");

    useEffect(() => {
        let animDuration = 1000;

        if (type === 'K') {
            setLabel("EXECUTE");
            setColorClass("text-red-600 drop-shadow-[0_0_10px_rgba(220,38,38,0.8)]");
            animDuration = 1200;
        } else if (type === 'Q') {
            setLabel("SHIFT");
            setColorClass("text-fuchsia-500 drop-shadow-[0_0_10px_rgba(217,70,239,0.8)]");
            animDuration = 1000;
        } else if (type === 'J') {
            setLabel("REINFORCE");
            setColorClass("text-emerald-500 drop-shadow-[0_0_10px_rgba(16,185,129,0.8)]");
            animDuration = 800;
        }

        requestAnimationFrame(() => {
            const destX = targetRect ? targetRect.left + targetRect.width / 2 : window.innerWidth / 2;
            const destY = targetRect ? targetRect.top + targetRect.height / 2 : window.innerHeight / 2;

            const finalLeft = type === 'J' ? '50%' : destX;
            const finalTop = type === 'J' ? '50%' : destY;
            const transform = type === 'J' ? 'translate(-50%, -50%) scale(1.2)' : 'translate(-50%, -50%) scale(1.5)';

            setStyle({
                position: 'fixed',
                left: finalLeft,
                top: finalTop,
                transform: transform,
                opacity: 1,
                zIndex: 200,
                transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
            });
        });

        setTimeout(onComplete, animDuration);
    }, []);

    return (
        <div style={style} className="flex flex-col items-center justify-center pointer-events-none">
            <div className={`shadow-[0_0_50px_rgba(255,255,255,0.2)] rounded-lg ${type === 'Q' ? 'animate-pulse' : ''}`}>
                <CardDisplay card={card} size="lg" showBack={false} />
            </div>
            <div className={`mt-4 text-4xl font-black font-title uppercase tracking-widest ${colorClass} animate-bounce`}>
                {label}
            </div>
        </div>
    );
};

import { useState, useCallback } from 'react';
import { Card, FlyingCard, FlyingText, SoulTrail, SummoningCard } from '../types';
import { generateId } from '../utils/core';

interface DamageAnimInstance {
    id: string;
    val: number;
    playerId: number;
    onApply?: () => void;
}

export const useGameEffects = () => {
    const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
    const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);
    const [summoningCards, setSummoningCards] = useState<SummoningCard[]>([]);
    const [soulTrails, setSoulTrails] = useState<SoulTrail[]>([]);
    const [explosions, setExplosions] = useState<{ id: string, x: number, y: number }[]>([]);
    const [damageAnims, setDamageAnims] = useState<DamageAnimInstance[]>([]);
    const [specialAnim, setSpecialAnim] = useState<{ type: 'K'|'Q'|'J', card: Card, targetRect?: DOMRect } | null>(null);
    const [showTurnAnim, setShowTurnAnim] = useState(false);
    const [screenShake, setScreenShake] = useState<{ intensity: number } | null>(null);

    const triggerFlyer = useCallback(async (
        card: Card, 
        startRect: DOMRect, 
        targetRect: DOMRect, 
        showFace: boolean = false, 
        onComplete?: () => void,
        pauseDuration?: number
    ): Promise<void> => {
        return new Promise(resolve => {
            const id = generateId();

            const handleComplete = () => {
                setFlyingCards(prev => prev.filter(f => f.id !== id));
                if (onComplete) onComplete();
                resolve();
            };

            const newFly: FlyingCard = {
                id, card, 
                startX: startRect.left, 
                startY: startRect.top, 
                targetX: targetRect.left + targetRect.width / 2 - 40, // Centering for md card (80px width)
                targetY: targetRect.top + targetRect.height / 2 - 56, // Centering for md card (112px height)
                showFace,
                pauseDuration,
                onComplete: handleComplete
            };
            setFlyingCards(prev => [...prev, newFly]);
        });
    }, []);

    const triggerSummon = useCallback(async (
        card: Card,
        startRect: DOMRect,
        targetElementId: string,
        ownerId: number
    ): Promise<void> => {
        return new Promise(resolve => {
            const id = generateId();

            const handleComplete = () => {
                setSummoningCards(prev => prev.filter(s => s.id !== id));
                resolve();
            };

            const newSummon: SummoningCard = {
                id,
                card,
                startX: startRect.left,
                startY: startRect.top,
                targetElementId,
                ownerId,
                onComplete: handleComplete
            };
            setSummoningCards(prev => [...prev, newSummon]);
        });
    }, []);

    const triggerExplosion = useCallback((instanceId: string) => {
        const el = document.getElementById(instanceId);
        if (el) {
            const rect = el.getBoundingClientRect();
            setExplosions(prev => [...prev, { id: generateId(), x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }]);
        }
    }, []);

    const removeExplosion = useCallback((id: string) => {
        setExplosions(prev => prev.filter(e => e.id !== id));
    }, []);

    const triggerSoulTrail = useCallback((instanceId: string, targetRect: DOMRect, color: string = 'cyan') => {
        const el = document.getElementById(instanceId);
        if (el) {
            const rect = el.getBoundingClientRect();
            const id = generateId();
            setSoulTrails(prev => [...prev, {
                id,
                startX: rect.left + rect.width / 2,
                startY: rect.top + rect.height / 2,
                targetX: targetRect.left + targetRect.width / 2,
                targetY: targetRect.top + targetRect.height / 2,
                color
            }]);
            setTimeout(() => {
                setSoulTrails(prev => prev.filter(s => s.id !== id));
            }, 800);
        }
    }, []);

    const addDamageAnim = useCallback((val: number, playerId: number, onApply?: () => void) => {
        setDamageAnims(prev => [...prev, { id: generateId(), val, playerId, onApply }]);
    }, []);

    const triggerScreenShake = useCallback((intensity: number) => {
        setScreenShake({ intensity });
        setTimeout(() => setScreenShake(null), 300);
    }, []);

    return {
        flyingTexts, setFlyingTexts,
        flyingCards, triggerFlyer,
        summoningCards, triggerSummon,
        soulTrails, triggerSoulTrail,
        explosions, triggerExplosion, removeExplosion,
        damageAnims, setDamageAnims, addDamageAnim,
        specialAnim, setSpecialAnim,
        showTurnAnim, setShowTurnAnim,
        screenShake, triggerScreenShake
    };
};

import React from 'react';
import { GameState, Card, Rank, Color } from '../../types';
import { createFieldCard, getEffectiveColor } from '../../utils/rules';
import { addLog } from '../../utils/core';
import { playSound } from '../../utils/soundUtils';

interface UseCardActionsProps {
    gameStateRef: React.MutableRefObject<GameState | null>;
    setGameState: React.Dispatch<React.SetStateAction<GameState | null>>;
    effects: any;
    refs: any;
    drawCards: (playerId: number, count: number) => Promise<void>;
}

export const useCardActions = ({ gameStateRef, setGameState, effects, refs, drawCards }: UseCardActionsProps) => {

    const formatCardLog = (card: Card) => `[${card.rank}${card.suit}]`;

    const playCard = async (card: Card, targetId?: string, targetOwnerId?: number) => {
        const isFaceCard = ['K', 'Q', 'J'].includes(card.rank);
        const currentState = gameStateRef.current;
        if (!currentState) return;

        // --- VALIDATION & PREP ---
        if (card.rank === 'K' || card.rank === 'Q') {
            if (!targetId || targetOwnerId === undefined) return;
            const targetP = currentState.players.find(p => p.id === targetOwnerId);
            const targetF = targetP?.field.find(f => f.instanceId === targetId);
            if (!targetF) return; 
            if (card.rank === 'K' && getEffectiveColor(targetF) !== card.baseColor) { 
                setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") }) : null);
                return; 
            }
        }

        // --- VISUAL SETUP ---
        // Capture start position before we remove it from state
        let startRect: DOMRect | undefined;
        const cardEl = document.getElementById(card.id);
        if (cardEl) {
            startRect = cardEl.getBoundingClientRect();
        } else {
            // Fallback for CPU offscreen
            const handContainer = currentState.turnPlayer === 0 ? refs.handRef.current : refs.cpuHandRef.current;
            if (handContainer) {
                const r = handContainer.getBoundingClientRect();
                startRect = { left: r.left + r.width/2, top: r.top + r.height/2, width: 0, height: 0, bottom: 0, right: 0, x: 0, y: 0, toJSON: () => {} } as DOMRect;
            }
        }

        let targetRect: DOMRect | undefined;
        if (targetId) { 
            const targetEl = document.getElementById(targetId); 
            if (targetEl) targetRect = targetEl.getBoundingClientRect(); 
        }

        if (isFaceCard) {
            // --- TACTICS LOGIC (Existing) ---
            setGameState(prev => {
                if (!prev) return null;
                const p = prev.players[prev.turnPlayer];
                const cardIdx = p.hand.findIndex(c => c.id === card.id);
                if (cardIdx === -1) return prev; 
                const newHand = [...p.hand];
                newHand.splice(cardIdx, 1); 

                let toTap = card.cost;
                const newResources = p.resources.map(r => {
                    if (!r.isTapped && toTap > 0) { toTap--; return { ...r, isTapped: true }; }
                    return r;
                });
                const nextPlayers = [...prev.players];
                nextPlayers[prev.turnPlayer] = { ...p, hand: newHand, resources: newResources };
                return { ...prev, players: nextPlayers };
            });

            playSound('tactic');
            if (card.rank === 'K') playSound('king');
            if (card.rank === 'Q') playSound('queen');

            effects.setSpecialAnim({ type: card.rank as 'K'|'Q'|'J', card, targetRect });
            await new Promise(r => setTimeout(r, card.rank === 'K' ? 1200 : card.rank === 'Q' ? 1000 : 800));
            effects.setSpecialAnim(null);

            setGameState(prev => {
                if (!prev) return null;
                const nextState = { ...prev, players: [...prev.players] };
                const p = nextState.players[prev.turnPlayer];

                if (card.rank === 'J') { 
                    p.discard.push(card); 
                    return { ...nextState, logs: addLog(nextState, `Played Jack ${formatCardLog(card)}.`) }; 
                } 
                else if (card.rank === 'K') {
                    const targetP = nextState.players[targetOwnerId!];
                    const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
                    if (targetFIdx === -1) return prev; 
                    const targetF = targetP.field[targetFIdx];

                    effects.triggerExplosion(targetId!); 
                    playSound('destroy');
                    effects.triggerScreenShake(4); 

                    const isSpectate = nextState.players[0].isCpu && nextState.players[1].isCpu;
                    const isHotseat = !nextState.players[1].isCpu || nextState.players[0].isCpu;
                    const viewId = (isHotseat && !isSpectate) ? nextState.turnPlayer : 0;
                    const isTop = targetOwnerId !== viewId;
                    const targetRef = isTop ? refs.topDiscardRef : refs.bottomDiscardRef;

                    if (targetRef.current && targetId) {
                        const trailColor = getEffectiveColor(targetF) === Color.Red ? 'red' : 'cyan';
                        effects.triggerSoulTrail(targetId, targetRef.current.getBoundingClientRect(), trailColor);
                    }

                    p.discard.push(card); 
                    targetP.field.splice(targetFIdx, 1); 
                    targetP.discard.push(targetF.card, ...targetF.attachedCards);
                    return { ...nextState, logs: addLog(nextState, `King ${formatCardLog(card)} executed ${formatCardLog(targetF.card)}.`) };
                } 
                else if (card.rank === 'Q') {
                    const targetP = nextState.players[targetOwnerId!];
                    const targetF = targetP.field.find(f => f.instanceId === targetId);
                    if(targetF) {
                        const existingQueens = targetF.attachedCards.filter(c => c.rank === Rank.Queen);
                        if (existingQueens.length > 0) { targetP.discard.push(...existingQueens); targetF.attachedCards = targetF.attachedCards.filter(c => c.rank !== Rank.Queen); }
                        targetF.attachedCards.push(card);
                    }
                    return { ...nextState, logs: addLog(nextState, `Queen ${formatCardLog(card)} shifted ${targetF ? formatCardLog(targetF.card) : 'target'}.`) };
                }
                return nextState;
            });

            if (card.rank === 'J' && gameStateRef.current) { await drawCards(gameStateRef.current.turnPlayer, 2); }

        } else {
            // --- SOLDIER LOGIC (REFINED ANIMATION) ---
            if (card.baseColor === Color.Red) playSound('conscript_mag');
            else playSound('conscript_phy');

            const pId = currentState.turnPlayer;
            const newSoldier = createFieldCard(card, pId);
            if (currentState.mode === 'TUTORIAL') newSoldier.instanceId = card.id;
            newSoldier.isBeingSummoned = true; // MARK INVISIBLE

            // STEP 1: Add to field immediately (Invisible) to reserve layout space
            setGameState(prev => {
                if (!prev) return null;
                const p = prev.players[prev.turnPlayer];
                const cardIdx = p.hand.findIndex(c => c.id === card.id);
                if (cardIdx === -1) return prev;

                const newHand = [...p.hand];
                newHand.splice(cardIdx, 1);

                let toTap = card.cost;
                const newResources = p.resources.map(r => {
                    if (!r.isTapped && toTap > 0) { toTap--; return { ...r, isTapped: true }; }
                    return r;
                });

                const nextPlayers = [...prev.players];
                const nextP = { ...p, hand: newHand, resources: newResources };
                nextP.field.push(newSoldier); // Push phantom

                nextPlayers[prev.turnPlayer] = nextP;
                return { ...prev, players: nextPlayers, logs: addLog(prev, `Conscripted ${formatCardLog(card)}.`) };
            });

            // STEP 2: Wait for DOM Reflow
            await new Promise(r => setTimeout(r, 50));

            // STEP 3: Animate to the exact reserved position
            if (startRect) {
                // Now that the invisible card is in DOM, we can target it
                await effects.triggerSummon(card, startRect, newSoldier.instanceId, pId);
            }

            // STEP 4: Reveal
            if (card.numericValue >= 7) playSound('damage_md'); // Heavy thud landing
            setGameState(prev => {
                if (!prev) return null;
                const nextPlayers = [...prev.players];
                const p = nextPlayers[prev.turnPlayer];
                const fieldIdx = p.field.findIndex(f => f.instanceId === newSoldier.instanceId);
                if (fieldIdx !== -1) {
                    p.field[fieldIdx].isBeingSummoned = false; // Reveal
                }
                return { ...prev, players: nextPlayers };
            });
        }
    };

    return { playCard };
};

import React from 'react';
